comms.text:
@1 וּמַלִּיל יְיָ עִם משֶׁה לְמֵימָר:
@2 דָּא תְהֵי אוֹרַיְתָא דִסְגִירָא בִּיוֹמָא דְדָכוּתֵיהּ וְיִתֵּתֵי לְוָת כַּהֲנָא:
@3 וְיִפּוֹק כַּהֲנָא לְמִבָּרָא לְמַשְׁרִיתָא וְיֶחֱזֵי כַהֲנָא וְהָא אִתַּסִּי מַכְתַּשׁ סְגִירוּתָא מִן סְגִירָא:
@4 וִיפַקֵּד כַּהֲנָא וְיִסַּב לְמִדַּכֵּי תַּרְתֵּין צִפְּרִין חַיִּין דָּכְיָן וְאָעָא דְאַרְזָא וּצְבַע זְהוֹרִי וְאֵזוֹבָא:
@5 וִיפַקֵּד כַּהֲנָא וְיִכּוֹס יָת צִפְּרָא חֲדָא לְמַאן דַּחֲסַף עַל מֵי מַבּוּעַ:
@6 יָת צִפְּרָא חַיְתָא יִסַּב יָתַהּ וְיָת אָעָא דְאַרְזָא וְיָת צְבַע זְהוֹרִי וְיָת אֵזוֹבָא וְיִטְבּוֹל יָתְהוֹן וְיָת צִפְּרָא חַיְתָא בִּדְמָא דְּצִפְּרָא דִּנְכִיסָא עַל מֵי מַבּוּעַ:
@7 וְיַדִּי עַל דְּמִדַּכֵּי מִן סְגִירוּתָא שְׁבַע זִמְנִין וִידַכִּנֵּיהּ וִישַׁלַּח יָת צִפְּרָא חַיְתָא עַל אַפֵּי חַקְלָא:
@8 וִיצַבַּע דְּמִדַּכֵּי יָת לְבוּשׁוֹהִי וִיגַלַּח יָת כָּל שַׂעֲרֵיהּ וְיַסְחֵי בְמַיָּא וְיִדְכֵּי וּבָתַר כֵּן יֵעוֹל לְמַשְׁרִיתָא וִיתֵב מִבָּרָא לְמַשְׁכְּנֵיהּ שַׁבְעָא יוֹמִין:
@9 וִיהֵי בְיוֹמָא שְׁבִיעָאָה יְגַלַּח יָת כָּל שַׂעֲרֵיהּ יָת רֵישֵׁיהּ וְיָת דִּקְנֵיהּ וְיָת גְּבִינֵי עֵינוֹהִי וְיָת כָּל שַׂעֲרֵיהּ יְגַלָּח וִיצַבַּע יָת לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵיהּ בְּמַיָּא וְיִדְכֵּי:
@10 וּבְיוֹמָא תְמִינָאָה יִסַּב תְּרֵין אִמְּרִין שַׁלְמִין וְאִמַּרְתָּא חֲדָא בַּת שַׁתָּא שְׁלֶמְתָּא וּתְלָתָא עֶסְרוֹנִין סֻלְתָּא מִנְחָתָא דְּפִילָא בִמְשַׁח וְלֻגָּא חַד דְּמִשְׁחָא:
@11 וִיקִים כַּהֲנָא דִמְדַּכֵּי יָת גַּבְרָא דְּמִדַּכֵּי וְיָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@12 וְיִסַּב כַּהֲנָא יָת אִמְּרָא חֲדָא וִיקָרֵב יָתֵיהּ לַאֲשָׁמָא וְיָת לֻגָּא דְמִשְׁחָא וִירִים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@13 וְיִכּוֹס יָת אִמְּרָא בַּאֲתַר דִּי יִכּוֹס יָת חַטָּאתָא וְיָת עֲלָתָא בַּאֲתַר קַדִּישׁ אֲרֵי כְּחַטָּאתָא אֲשָׁמָא הוּא לְכַהֲנָא קֹדֶשׁ קוּדְשִׁין הוּא:
@14 וְיִסַּב כַּהֲנָא מִדְּמָא דַאֲשָׁמָא וְיִתֵּן כַּהֲנָא עַל רוּם אוּדְנָא דְמִדַּכֵּי דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְּיַמִּינָא:
@15 וְיִסַּב כַּהֲנָא מִלֻּגָּא דְמִשְׁחָא וִירִיק עַל יְדָא דְכַהֲנָא דִּשְׂמָאלָא:
@16 וְיִטְבּוֹל כַּהֲנָא יָת אֶצְבְּעֵיהּ דְיַמִּינָא מִן מִשְׁחָא דִּי עַל יְדֵיהּ דִּשְׂמָאלָא וְיַדִּי מִן מִשְׁחָא בְּאֶצְבְּעֵיהּ שְׁבַע זִמְנִין קֳדָם יְיָ:
@17 וּמִשְּׁאָר מִשְׁחָא דִּי עַל יְדֵיהּ יִתֵּן כַּהֲנָא עַל רוּם אוּדְנָא דְּמִדַּכֵּי דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְּיַמִּינָא עַל דְּמָא דַאֲשָׁמָא:
@18 וּדְאִשְׁתָּאַר בְּמִשְׁחָא דִּי עַל יְדָא דְכַהֲנָא יִתֵּן עַל רֵישָׁא דְּמִדַּכֵּי וִיכַפֵּר עֲלוֹהִי כַּהֲנָא קֳדָם יְיָ:
@19 וְיַעְבֵּד כַּהֲנָא יָת חַטָּאתָא וִיכַפֵּר עַל דְּמִדַּכֵּי מְסּוֹבְתֵיהּ וּבָתַר כֵּן יִכּוֹס יָת עֲלָתָא:
@20 וְיַסֵּק כַּהֲנָא יָת עֲלָתָא וְיָת מִנְחָתָא לְמַדְבְּחָא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא וְיִדְכֵּי:
@21 וְאִם מִסְכֵּן הוּא וְלֵית יְדֵיהּ מַדְבְּקָא וְיִסַּב אִמַּר חַד אֲשָׁמָא לַאֲרָמָא לְכַפָּרָא עֲלוֹהִי וְעִסְרוֹנָא סֻלְתָּא חַד דְּפִיל בִּמְשַׁח לְמִנְחָא וְלֻגָּא דְמִשְׁחָא:
@22 וְתַרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה דִּי תַדְבֵּק יְדֵיהּ וִיהֵי חַד חַטָּאתָא וְחַד עֲלָתָא:
@23 וְיַיְתִי יָתְהוֹן בְּיוֹמָא תְמִינָאָה לְדַכָּיוּתֵיהּ לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא קֳדָם יְיָ:
@24 וְיִסַּב כַּהֲנָא יָת אִמְּרָא דַאֲשָׁמָא וְיָת לֻגָּא דְמִשְׁחָא וִירִים יָתְהוֹן כַּהֲנָא אֲרָמָא קֳדָם יְיָ:
@25 וְיִכּוֹס יָת אִמְּרָא דַאֲשָׁמָא וְיִסַּב כַּהֲנָא מִדְּמָא דַאֲשָׁמָא וְיִתֵּן עַל רוּם אוּדְנָא דְמִדַּכֵּי דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְּיַמִּינָא:
@26 וּמִן מִשְׁחָא יְרִיק כַּהֲנָא עַל יְדָא דְכַהֲנָא דִּשְׂמָאלָא:
@27 וְיַדִּי כַהֲנָא בְּאֶצְבְּעֵיהּ דְּיַמִּינָא מִן מִשְׁחָא דִּי עַל יְדֵיהּ דִּשְׂמָאלָא שְׁבַע זִמְנִין קֳדָם יְיָ:
@28 וְיִתֵּן כַּהֲנָא מִן מִשְׁחָא דִּי עַל יְדֵיהּ עַל רוּם אוּדְנָא דְמִדַּכֵּי דְּיַמִּינָא וְעַל אִלְיוֹן יְדֵיהּ דְּיַמִּינָא וְעַל אִלְיוֹן רַגְלֵיהּ דְיַמִּינָא עַל אֲתַר דְּמָא דַאֲשָׁמָא:
@29 וּדְיִשְׁתָּאַר מִן מִשְׁחָא דִּי עַל יְדָא דְכַהֲנָא יִתֵּן עַל רֵישָׁא דְמִדַּכֵּי לְכַפָּרָא עֲלוֹהִי קֳדָם יְיָ:
@30 וְיַעְבֵּד יָת חַד מִן שַׁפְנִינַיָּא אוֹ מִן בְּנֵי יוֹנָה מִדִּי תַדְבֵּק יְדֵיהּ:
@31 יָת דִּי תַדְבֵּק יְדֵיהּ יָת חַד חַטָּאתָא וְיָת חַד עֲלָתָא עַל מִנְחָתָא וִיכַפֵּר כַּהֲנָא עַל דְּמִדַּכֵּי קֳדָם יְיָ:
@32 דָּא אוֹרַיְתָא דִּי בֵיהּ מַכְתַּשׁ סְגִירוּ דִּי לָא תַדְבֵּק יְדֵיהּ בְּדָכוּתֵיהּ:
@33 וּמַלִּיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@34 אֲרֵי תֵעֲלוּן לְאַרְעָא דִכְנַעַן דִּי אֲנָא יָהֵב לְכוֹן לְאַחֲסָנָא וְאֶתֵּן מַכְתַּשׁ סְגִירוּ בְּבֵית אַרְעָא אַחֲסְנְתְּכוֹן:
@35 וְיֵיתֵי דְּדִילֵיהּ בֵּיתָא וִיחַוִּי לְכַהֲנָא לְמֵימָר כְּמַכְתָּשָׁא אִתְחֲזִי לִי בְּבֵיתָא:
@36 וִיפַקֵּד כַּהֲנָא וִיפַנּוּן יָת בֵּיתָא עַד לָא יֵעוֹל כַּהֲנָא לְמֶחֱזֵי יָת מַכְתָּשָׁא וְלָא יִסְתָּאַב כָּל דִּי בְּבֵיתָא וּבָתַר כֵּן יֵעוֹל כַּהֲנָא לְמֶחֱזֵי יָת בֵּיתָא:
@37 וְיֶחֱזֵי יָת מַכְתָּשָׁא וְהָא מַכְתָּשָׁא בְּכָתְלֵי בֵיתָא פַּחֲתִין יַרְקָן אוֹ סַמְקָן וּמֶחֱזֵיהוֹן מַכִּיךְ מִן כָּתְלָא:
@38 וְיִפּוֹק כַּהֲנָא מִן בֵּיתָא לִתְרַע בֵּיתָא וְיַסְגַּר יָת בֵּיתָא שִׁבְעָא יוֹמִין:
@39 וִיתוּב כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה וְיֶחֱזֵי וְהָא אוֹסִיף מַכְתָּשָׁא בְּכָתְלֵי בֵיתָא:
@40 וִיפַקֵּד כַּהֲנָא וִישַׁלְּפוּן יָת אַבְנַיָּא דִּי בְהוֹן מַכְתָּשָׁא וְיִרְמוּן יָתְהוֹן לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:
@41 וְיָת בֵּיתָא יְקַלְּפוּן מִגָּיו סְחוֹר סְחוֹר וְיִרְמוּן יָת עַפְרָא דִּי קַלִּיפוּ לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:
@42 וְיִסְּבוּן אַבְנַיָּא אָחֳרָנִין וְיַעֲלוּן לַאֲתַר אַבְנַיָּא וַעֲפַר אָחֳרָן יִסַּב וִישׁוּעַ יָת בֵּיתָא:
@43 וְאִם יְתוּב מַכְתָּשָׁא וְיִסְגֵּי בְּבֵיתָא בָּתַר דְּשַׁלִּיפוּ יָת אַבְנַיָּא וּבָתַר דְקַלִּיפוּ יָת בֵּיתָא וּבָתַר דְּאִתְּשָׁע:
@44 וְיֵיעוֹל כַּהֲנָא וְיֶחֱזֵי וְהָא אוֹסֵף מַכְתָּשָׁא בְּבֵיתָא סְגִירוּת מְחַסְרָא הִיא בְּבֵיתָא מְסָאָב הוּא:
@45 וִיתָרַע יָת בֵּיתָא יָת אַבְנוֹהִי וְיָת אָעוֹהִי וְיָת כָּל עֲפַר בֵּיתָא וְיַפֵּק לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:
@46 וּדְיֵיעוֹל לְבֵיתָא כָּל יוֹמִין דְּיַסְגַּר יָתֵיהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@47 וּדְיִשְׁכּוּב בְּבֵיתָא יְצַבַּע יָת לְבוּשׁוֹהִי וּדְיֵיכוּל בְּבֵיתָא יְצַבַּע יָת לְבוּשׁוֹהִי:
@48 וְאִם מֵעַל יֵיעוֹל כַּהֲנָא וְיֶחֱזֵי וְהָא לָא אוֹסֵף מַכְתָּשָׁא בְּבֵיתָא בָּתַר דְּאִתְּשַׁע יָת בֵּיתָא וִידַכֵּי כַהֲנָא יָת בֵּיתָא אֲרֵי אִתַּסִּי מַכְתָּשָׁא:
@49 וְיִסַּב לְדַכָּאָה יָת בֵּיתָא תַּרְתֵּין צִפְּרִין וְאָעָא דְאַרְזָא וּצְבַע זְהוֹרִי וְאֵזוֹבָא:
@50 וְיִכּוֹס יָת צִפֲּרָא חֲדָא לְמַאן דַּחֲסַף עַל מֵי מַבּוּעַ:
@51 וְיִסַּב יָת אָעָא דְאַרְזָא וְיָת אֵזוֹבָא וְיָת צְבַע זְהוֹרִי וְיָת צִפֲּרָא חַיְתָא וְיִטְבּוֹל יָתְהוֹן בִּדְמָא דְּצִפֲּרָא דִנְכִיסָא וּבְמֵי מַבּוּעַ וְיַדִּי לְבֵיתָא שְׁבַע זִמְנִין:
@52 וִידַכֵּי יָת בֵּיתָא בִּדְמָא דְּצִפֲּרָא וּבְמֵי מַבּוּעַ וּבְצִפֲּרָא חַיְתָא וּבְאָעָא דְאַרְזָא וּבְאֵזוֹבָא וּבִצְבַע זְהוֹרִי:
@53 וִישַׁלַּח יָת צִפֲּרָא חַיְתָא לְמִבָּרָא לְקַרְתָּא לְאַפֵּי חַקְלָא וִיכַפַּר עַל בֵּיתָא וְיִדְכֵּי:
@54 דָּא אוֹרַיְתָא לְכָל מַכְתַּשׁ סְגִירוּתָא וּלְנִתְקָא:
@55 וְלִסְגִירוּת לְבוּשָׁא וּלְבֵיתָא:
@56 וּלְעַמְקָא וּלְעַדְיָא וּלְבַהֲרָא:
@57 לְאַלָּפָא בְּיוֹמָא מְסָאָבָא וּבְיוֹמָא דַכְיָא דָּא אוֹרַיְתָא דִּסְגִירוּתָא:
@58 וּמַלִּיל יְיָ עִם משֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@59 מַלִּילוּ עִם בְּנֵי יִשְׂרָאֵל וְתֵימְרוּן לְהוֹן גְּבַר גְּבַר אֲרֵי יְהֵי דָּאִיב מִבִּשְׂרֵיהּ דּוֹבֵיהּ מְסָאָב הוּא:
@60 וְדָא תְּהֵי סוֹבְתֵיהּ בְּדוֹבֵיהּ רָר בִּשְׂרֵיהּ יָת דּוֹבֵיהּ אוֹ חָתִים בִּשְׂרֵיהּ מִדּוֹבֵיהּ סוֹבְתֵיהּ הִיא:
@61 כָּל מִשְׁכְּבָא דִּי יִשְׁכּוּב עֲלוֹהִי דּוֹבָנָא יְהֵי מְסָאָב וְכָל מָנָא דְיֵיתֵב עֲלוֹהִי יְהֵי מְסָאָב:
@62 וּגְבַר דִּי יִקְרַב בּמִשְׁכְּבֵיהּ יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@63 וּדְיֵיתֵב עַל מָנָא דְּיֵיתֵב עֲלוֹהִי דּוֹבָנָא יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@64 וּדְיִקְרַב בִּבְסַר דּוֹבָנָא יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@65 וַאֲרֵי יֵרוֹק דּוֹבָנָא בְּדַכְיָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@66 וְכָל מֶרְכְּבָא דִּי יִרְכּוּב עֲלוֹהִי דּוֹבָנָא יְהֵי מְסָאָב:
@67 וְכָל דְּיִקְרַב בְּכֹל דִּי יְהֵי תְחוֹתוֹהִי יְהֵי מְסָאָב עַד רַמְשָׁא וּדְיִטּוֹל יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@68 וְכֹל דִּי יִקְרַב בֵּיהּ דּוֹבָנָא וִידוֹהִי לָא שְׁטַף בְּמַיָּא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@69 וּמַאן דַּחֲסַף דִּי יִקְרַב בֵּיהּ דּוֹבָנָא יִתָּבַר וְכָל מַאן דְּאָע יִשְׁתַּטַּף בְּמַיָּא:
@70 וַאֲרֵי יִדְכֵּי דּוֹבָנָא מִדּוֹבֵיהּ וְיִמְנֵי לֵיהּ שִׁבְעַת יוֹמִין לְדָכוּתֵיהּ וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בִשְׂרֵיהּ בְּמֵי מַבּוּעַ וְיִדְכֵּי:
@71 וּבְיוֹמָא תְמִינָאָה יִסַּב לֵיהּ תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה וְיֵיתֵי לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא וְיִתְּנִנּוּן לְכַהֲנָא:
@72 וְיַעְבֵּד יָתְהוֹן כַּהֲנָא חַד חַטָּאתָא וְחַד עֲלָתָא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא קֳדָם יְיָ מִדּוֹבֵיהּ:
@73 וּגְבַר אֲרֵי תִפּוֹק מִנֵּיהּ שִׁכְבַת זַרְעָא וְיַסְחֵי בְמַיָּא יָת כָּל בִּשְׂרֵיהּ וִיהֵי מְסָאָב עַד רַמְשָׁא:
@74 וְכָל לְבוּשׁ וְכָל מְשַׁךְ דִּי יְהֵי עֲלוֹהִי שִׁכְבַת זַרְעָא וְיִצְטַבַּע בְּמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@75 וְאִתְּתָא דִּי יִשְׁכּוּב גְּבַר יָתַהּ שִׁכְבַת זַרְעָא וְיַסְחוּן בְּמַיָּא וְיִסְאֲבוּן עַד רַמְשָׁא:
@76 וְאִתְּתָא אֲרֵי תְהֵי דָיְבָא דָּם יְהֵי דוֹבַהּ בְּבִשְׂרַהּ שִׁבְעָא יוֹמִין תְּהֵי בְרִיחוּקַהּ וְכָל דְּיִקְרַב בַּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@77 וְכֹל דִּי תִשְׁכּוּב עֲלוֹהִי בְּרִחוּקַהּ יְהֵי מְסָאָב וְכֹל דִּי תֵיתֵב עֲלוֹהִי יְהֵי מְסָאָב:
@78 וְכָל דְּיִקְרַב בְּמִשְׁכְּבַהּ יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@79 וְכָל דְּיִקְרַב בְּכָל מָנָא דִּי תֵיתֵב עֲלוֹהִי יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@80 וְאִם עַל מִשְׁכְּבָא הוּא אוֹ עַל מָנָא דִּי הִא יָתְבָא עֲלוֹהִי בְּמִקְרְבֵיהּ בֵּיהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@81 וְאִם מִשְׁכַּב יִשְׁכּוּב גְּבַר יָתַהּ וּתְהֵי רִחוּקַהּ עֲלוֹהִי וִיהֵי מְסָאָב שִׁבְעַת יוֹמִין וְכָל מִשְׁכְּבָא דִּי יִשְׁכּוּב עֲלוֹהִי יְהֵי מְסָאָב:
@82 וְאִתְּתָא אֲרֵי יְדוּב דּוֹב דְּמַהּ יוֹמִין סַגִּיאִין בְּלָא עִדַּן רִחוּקַהּ אוֹ אֲרֵי תְדוּב עַל רִחוּקַהּ כָּל יוֹמֵי דּוֹב סוֹבְתַהּ כְּיוֹמֵיהּ רִחוּקַהּ תְּהֵי מְסָאֳבָא הִיא:
@83 כָּל מִשְׁכְּבָא דִּי תִשְׁכּוּב עֲלוֹהִי כָּל יוֹמֵי דוֹבַהּ כְּמִשְׁכַּב רִחוּקַהּ יְהֵי לַהּ וְכָל מָנָא דִּי תֵתֵב עֲלוֹהִי מְסָאָב יְהֵי כְּסוֹאֲבַת רִחוּקַהּ:
@84 וְכָל דְּיִקְרַב בְּהוֹן יְהֵי מְסָאָב וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָּא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@85 וְאִם דְּכִיאַת מִדּוֹבַהּ וְתִמְנֵי לַהּ שִׁבְעַת יוֹמִין וּבָתַר כֵּן תִּדְכֵּי:
@86 וּבְיוֹמָא תְמִינָאָה תִּסַּב לַהּ תַּרְתֵּין שַׁפְנִינִין אוֹ תְּרֵין בְּנֵי יוֹנָה וְתַיְתִי יָתְהוֹן לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא:
@87 וְיַעְבֵּד כַּהֲנָא יָת חַד חַטָּאתָא וְיָת חַד עֲלָתָא וִיכַפֵּר עֲלַהּ כַּהֲנָא קֳדָם יְיָ מִדּוֹב סוֹבְתַהּ:
@88 וְתַפְרְשׁוּן יָת בְּנֵי יִשְׂרָאֵל מִסּוֹאֲבַתְהוֹן וְלָא יְמוּתוּן בְּסוֹאֲבַתְהוֹן בְּסָאָבְהוֹן יָת מַשְׁכְּנִי דִּי בֵינֵיהוֹן:
@89 דָּא אוֹרַיְתָא דְּדוֹבְנָא וְדִי תִפּוֹק מִנֵּיהּ שִׁכְבַת זַרְעָא לְאִסְתָּאָבָא בַהּ:
@90 וְלִדְסָאוּבְתָּא בְּרִיחוּקַהּ וְלִדְדָאִיב יָת דּוֹבֵיהּ לִדְכַר וּלְנֻקְבָּא וְלִגְבַר דִּי יִשְׁכּוּב עִם מְסָאָבָא:

@2 **זאת תהיה תורת וגו'.** מְלַמֵּד שֶׁאֵין מְטַהֲרִין אוֹתוֹ בַּלַּיְלָה (ספרא):
@3 **אל מחוץ למחנה.** חוּץ לִשְׁלוֹשָׁה מַחֲנוֹת שֶׁנִּשְׁתַּלַח שָׁם בִּימֵי חֲלוּטוֹ:
@4 **חיות.** פְּרָט לִטְרֵפוֹת:
@4 **טהרות.** פְּרָט לְעוֹף טָמֵא, לְפִי שֶׁהַנְּגָעִים בָּאִין עַל לָשׁוֹן הָרַע שֶׁהוּא מַעֲשֵׂה פִטְפּוּטֵי דְבָרִים, לְפִיכָךְ הֻזְקְקוּ לְטָהֳרָתוֹ צִפֳּרִים שֶׁמְּפַטְפְּטִין תָּמִיד בְּצִפְצוּף קוֹל (ערכין ט"ז):
@4 **ועץ ארז.** לְפִי שֶׁהַנְּגָעִים בָּאִין עַל גַּסּוּת הָרוּחַ (שם):
@4 **ושני תולעת ואזב.** מַה תַּקָּנָתוֹ וְיִתְרַפֵּא? יַשְׁפִּיל עַצְמוֹ מִגַּאֲוָתוֹ כְּתוֹלַעַת וּכְאֵזוֹב:
@4 **עץ ארז.** מַקֵּל שֶׁל אֶרֶז:
@4 **שני תולעת.** לָשׁוֹן שֶׁל צֶמֶר צָבוּעַ זְהוֹרִית:
@5 **על מים חיים.** נוֹתֵן אוֹתָם תְּחִלָּה בִּכְלִי, כְּדֵי שֶׁיְּהֵא דַם צִפּוֹר נִכָּר בָּהֶם, וְכַמָּה הֵם? רְבִיעִית (סוטה ט"ז):
@6 **את הצפר החיה יקח אתה.** מְלַמֵּד שֶׁאֵינוֹ אוֹגְדָהּ עִמָּהֶם, אֶלָּא מַפְרִישָׁהּ לְעַצְמָהּ, אֲבָל הָעֵץ וְהָאֵזוֹב כְּרוּכִין יַחַד בִּלְשׁוֹן הַזְּהוֹרִית, כָּעִנְיָן שֶׁנֶּאֱמַר וְאֶת עֵץ הָאֶרֶז וְאֶת שְׁנִי הַתּוֹלַעַת וְאֶת הָאֵזֹב — קִיחָה אַחַת לִשְׁלָשְׁתָּן; יָכוֹל כְּשֵׁם שֶׁאֵינָהּ בִּכְלַל אֲגֻדָּה, כָּךְ לֹא תְהֵא בִכְלַל טְבִילָה, תַּ"ל וְטָבַל אוֹתָם וְאֵת הַצִּפֹּר הַחַיָּה — הֶחֱזִיר אֶת הַצִּפּוֹר לִכְלַל טְבִילָה (ספרא):
@8 **וישב מחוץ לאהלו.** מְלַמֵּד שֶׁאָסוּר בְּתַשְׁמִישׁ הַמִּטָּה (שם):
@9 **את כל שערו וגו'.** כְּלָל וּפְרָט וּכְלָל, לְהָבִיא כָּל מְקוֹם כִּנּוּס שֵׂעָר וְנִרְאֶה (סוטה ט"ז):
@10 **וכבשה אחת.** לְחַטָּאת:
@10 **ושלשה עשרנים.** לְנִסְכֵּי שְׁלוֹשָׁה כְבָשִֹים הַלָּלוּ, שֶׁחַטָּאתוֹ וַאֲשָׁמוֹ שֶׁל מְצֹרָע טְעוּנִין נְסָכִים (מנחות צ"א):
@10 **ולג אחד שמן.** לְהַזּוֹת עָלָיו שֶׁבַע, וְלִתֵּן מִמֶּנּוּ עַל תְּנוּךְ אָזְנוֹ וּמַתַּן בְּהוֹנוֹת:
@11 **לפני ה'.** בְּשַׁעַר נִקָּנוֹר, וְלֹא בָעֲזָרָה עַצְמָהּ, לְפִי שֶׁהוּא מְחֻסָּר כִּפּוּרִים (כלים פ"א):
@12 **והקריב אתו לאשם.** יַקְרִיבֶנּוּ לְתוֹךְ הָעֲזָרָה לְשֵׁם אָשָׁם לְהָנִיף, שֶׁהוּא טָעוּן תְּנוּפָה חָי (מנחות ס"ב):
@12 **והניף אתם.** אֶת הָאָשָׁם וְאֶת הַלֹּג (שם ס"א):
@13 **במקום אשר ישחט וגו'.** עַל יֶרֶךְ הַמִּזְבֵּחַ בַּצָּפוֹן, וּמַה תַּלְמוּד לוֹמַר? וַהֲלֹא כְבָר נֶאֱמַר בְּתוֹרַת אָשָׁם בְפָרָשַׁת צַו אֶת אַהֲרֹן שֶׁהָאָשָׁם טָעוּן שְׁחִיטָה בַצָּפוֹן? לְפִי שֶׁיָּצָא זֶה מִכְּלַל אֲשָׁמוֹת לִדּוֹן בְּהַעֲמָדָה, יָכוֹל תְּהֵא שְׁחִיטָתוֹ בִּמְקוֹם הַעֲמָדָתוֹ, לְכָךְ נֶאֱמַר "וְשָׁחַט … בִּמְקוֹם אֲשֶׁר יִשְׁחַט וְגוֹ'" (ספרא):
@13 **כי כחטאת.** כִּי כְּכָל הַחַטָּאוֹת **האשם** הַזֶּה **הוא לכהן** — בְּכָל עֲבוֹדוֹת הַתְּלוּיוֹת בַּכֹּהֵן הֻשְׁוָה אָשָׁם זֶה לְחַטָּאת. שֶׁלֹּא תֹאמַר הוֹאִיל וְיָצָא דָמוֹ מִכְּלַל שְׁאָר אֲשָׁמוֹת לִנָּתֵן עַל תְּנוּךְ וּבְהוֹנוֹת, לֹא יְהֵא טָעוּן מַתַּן דָּמִים וְאֵמוּרִים לְגַבֵּי מִזְבֵּחַ, לְכָךְ נֶאֱמַר כִּי כַּחַטָּאת הָאָשָׁם הוּא לַכֹּהֵן יָכוֹל יְהֵא דָמוֹ נִתָּן לְמַעְלָה כַּחַטָּאת, תַּלְמוּד לוֹמַר וְכוּ' בְּתוֹרַת כֹּהֲנִים:
@14 **תנוך.** גָּדֵר אֶמְצָעִי שֶׁבָּאֹזֶן, וּלְשׁוֹן תְּנוּךְ לֹא נוֹדַע לִי, וְהַפּוֹתְרִים קוֹרִים לוֹ טנד"רום:
@14 **בהן.** גּוּדָל:
@16 **לפני ה'.** כְּנֶגֶד בֵּית קָדְשֵׁי הַקֳּדָשִׁים (ספרא):
@20 **ואת המנחה.** מִנְחַת נְסָכִים שֶׁל בְּהֵמָה:
@21 **ועשרון סלת אחד.** לְכֶבֶשׂ זֶה שֶׁהוּא אֶחָד, יָבִיא עִשָּׂרוֹן אֶחָד לִנְסָכָיו:
@21 **ולג שמן.** לָתֵת מִמֶּנּוּ עַל הַבְּהוֹנוֹת; וְשֶׁמֶן שֶׁל נִסְכֵּי הַמִּנְחָה לֹא הֻזְקַק הַכָּתוּב לְפָרֵשׁ:
@23 **ביום השמיני לטהרתו.** שְׁמִינִי לְצִפֳּרִים וּלְהַזָּאַת עֵץ אֶרֶז וְאֵזוֹב וּשְׁנִי תּוֹלַעַת:
@28 **על מקום דם האשם.** אֲפִלּוּ נִתְקַנַּח הַדָּם; לִמֵּד, שֶׁאֵין הַדָּם גּוֹרֵם אֶלָּא הַמָּקוֹם גּוֹרֵם (ספרא):
@34 **ונתתי נגע צרעת.** בְּשׂוֹרָה הִיא לָהֶם שֶׁהַנְּגָעִים בָּאִים עֲלֵיהֶם; לְפִי שֶׁהִטְמִינוּ אֱמוֹרִיִּים מַטְמוֹנִיּוֹת שֶׁל זָהָב בְּקִירוֹת בָּתֵּיהֶם כָּל אַרְבָּעִים שָׁנָה שֶׁהָיוּ יִשְֹרָאֵל בַּמִּדְבָּר, וְעַל יְדֵי הַנֶּגַע נוֹתֵץ הַבַּיִת וּמוֹצְאָן (ויקרא רבה י"ז):
@35 **כנגע נראה לי בבית.** שֶׁאֲפִלּוּ הוּא חָכָם וְיוֹדֵעַ שֶׁהוּא נֶגַע וַדַּאי, לֹא יִפְסֹק דָּבָר בָּרוּר לוֹמַר "נֶגַע נִרְאָה לִי", אֶלָּא "כְּנֶגַע נִרְאָה לִי":
@36 **בטרם יבא הכהן וגו'.** שֶׁכָּל זְמַן שֶׁאֵין כֹּהֵן נִזְקָק לוֹ, אֵין שָׁם תּוֹרַת טֻמְאָה:
@36 **ולא יטמא כל אשר בבית.** שֶׁאִם לֹא יְפַנֵּהוּ, וְיָבֹא הַכֹּהֵן וְיִרְאֶה הַנֶּגַע נִזְקָק לְהֶסְגֵּר וְכָל מַה שֶּׁבְּתוֹכוֹ יִטְמָא; וְעַל מָה חָסָה תוֹרָה? אִם עַל כְּלֵי שֶׁטֶף, יַטְבִּילֵם וְיִטְהֲרוּ, וְאִם עַל אֳכָלִין וּמַשְׁקִין, יֹאכְלֵם בִּימֵי טֻמְאָתוֹ, הָא לֹא חָסָה תוֹרָה אֶלָּא עַל כְּלֵי חֶרֶס, שֶׁאֵין לָהֶם טָהֳרָה בַּמִּקְוֶה (ספרא):
@37 **שקערורת.** שׁוֹקְעוֹת בְּמַרְאֵיהֶן (שם):
@40 **וחלצו את האבנים.** כְּתַרְגּוּמוֹ: וִיִשְׁלְפוּן — יִטְּלֵם מִשָּׁם, כְּמוֹ וְחָלְצָה נַעֲלוֹ (דברים כ"ה) — לְשׁוֹן הֲסָרָה:
@40 **אל מקום טמא.** מָקוֹם שֶׁאֵין טְהָרוֹת מִשְׁתַּמְּשׁוֹת שָׁם, לִמֶּדְךָ הַכָּתוּב שֶׁהָאֲבָנִים הַלָּלוּ מְטַמְּאוֹת מְקוֹמָן בְּעוֹדָן בּוֹ (ספרא):
@41 **יקצע.** רדויי"ר בְּלַעַז, וּבִלְשׁוֹן מִשְׁנָה יֵשׁ הַרְבֶּה:
@41 **מבית.** מִבִּפְנִים:
@41 **סביב.** סְבִיבוֹת הַנֶּגַע; בְּתֹ"כֹּ נִדְרַשׁ כֵּן — שֶׁיִּקְלֹף הַטִּיחַ שֶׁסְּבִיב אַבְנֵי הַנֶּגַע:
@41 **הקצו.** לְשׁוֹן קָצֶה — אֲשֶׁר קִצְּעוּ בִקְצוֹת הַנֶּגַע סָבִיב:
@43 **הקצות.** לְשׁוֹן הֵעָשׂוֹת, וְכֵן הִטּוֹחַ, אֲבָל חִלֵּץ אֶת הָאֲבָנִים מוּסָב הַלָּשׁוֹן אֶל הָאָדָם שֶׁחִלְּצָן, וְהוּא מִשְׁקַל לְשׁוֹן כָּבֵד, כְּמוֹ כִּפֵּר, דִּבֵּר:
@43 **ואם ישוב הנגע וגו'.** יָכוֹל חָזַר בּוֹ בַיּוֹם יְהֵא טָמֵא, תַּ"ל "וְשָׁב הַכֹּהֵן" "וְאִם יָשׁוּב", מַה שִּׁיבָה הָאָמוּר לְהַלָּן לְסוֹף שָׁבוּעַ, אַף שִׁיבָה הָאֲמוּרָה כָּאן בְּסוֹף שָׁבוּעַ (ספרא):
@44 **ובא הכהן וראה והנה פשה.** יָכוֹל לֹא יְהֵא הַחוֹזֵר טָמֵא אֶלָּא אִם כֵּן פָּשָׂה, נֶאֱמַר צָרַעַת מַמְאֶרֶת בַּבָּתִּים, וְנֶאֱמַר צָרַעַת מַמְאֶרֶת בַּבגדים, מַה לְּהַלָּן טִמֵּא אֶת הַחוֹזֵר אַעַ"פִּ שֶׁאֵינוֹ פוֹשֶׂה, אַף כָּאן טִמֵּא אֶת הַחוֹזֵר אַעַ"פִּ שֶׁאֵינוֹ פוֹשֶׂה, אִם כֵּן מַה תַּ"ל וְהִנֵּה פָשָׂה? אֵין כָּאן מְקוֹמוֹ שֶׁל מִקְרָא זֶה, אֶלָּא "וְנָתַץ אֶת הַבַּיִת" הָיָה לוֹ לִכְתֹּב אַחַר "וְאִם יָשׁוּב הַנֶּגַע"; "וְרָאָה וְהִנֵּה פָּשָׂה" הָא לֹא בָא לְלַמֵּד אֶלָּא עַל נֶגַע הָעוֹמֵד בְּעֵינָיו בְּשָׁבוּעַ רִאשׁוֹן, וּבָא בְסוֹף שָׁבוּעַ שֵׁנִי וּמְצָאוֹ שֶׁפָּשָׂה — שֶׁלֹּא פֵּרֵשׁ בּוֹ הַכָּתוּב לְמַעְלָה כְלוּם בְּעוֹמֵד בְּעֵינָיו בְּשָׁבוּעַ רִאשׁוֹן — וְלִמֶּדְךָ כָּאן בְּפִשְׂיוֹן זֶה, שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בְּעוֹמֵד בָּרִאשׁוֹן וּפָשָׂה בַשֵּׁנִי; וּמַה יַּעֲשֶׂה לּוֹ? יָכוֹל יִתְּצֶנּוּ, כְּמוֹ שֶׁסָּמַךְ לוֹ "וְנָתַץ אֶת הַבַּיִת", תַּ"ל וְשָׁב הַכֹּהֵן, וּבָא הַכֹּהֵן, נִלְמַד בִּיאָה מִשִּׁיבָה, מַה שִּׁיבָה חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ, אַף בִּיאָה חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ, וְאִם חוֹזֵר נוֹתֵץ, לֹא חָזַר טָהוֹר. וּמִנַּיִן שֶׁאִם עָמַד בָּזֶה וּבָזֶה חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ? תַּלְמוּד לוֹמַר וְאִם בֹּא יָבֹא, בַּמֶּה הַכָּתוּב מְדַבֵּר? אִם בְּפוֹשֶׂה בָּרִאשׁוֹן, הֲרֵי כְבָר אָמוּר, אִם בְּפוֹשֶׂה בַשֵּׁנִי, הֲרֵי כְבָר אָמוּר, הָא אֵינוֹ אוֹמֵר וְאִם בֹּא יָבֹא אֶלָּא אֶת שֶׁבָּא בְסוֹף שָׁבוּעַ רִאשׁוֹן וּבָא בְסוֹף שָׁבוּעַ שֵׁנִי וְרָאָה וְהִנֵּה לֹא פָשָׂה; זֶה הָעוֹמֵד מַה יַּעֲשֶׂה לוֹ? יָכוֹל יִפָּטֵר וְיֵלֵךְ, כְּמוֹ שֶׁכָּתוּב כָּאן וְטִהַר אֶת הַבַּיִת? תַּ"ל כִּי נִרְפָּא הַנָּגַע — לֹא טִהַרְתִּי אֶלָּא הָרָפוּי, מַה יַּעֲשֶׂה לוֹ? בִּיאָה אֲמוּרָה לְמַעְלָה וּבִיאָה אֲמוּרָה לְמַטָּה, מַה בָּעֶלְיוֹנָה חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ — דְּגָמַר לָהּ זֶהוּ שִׁיבָה זֶהוּ בִיאָה — אַף בַּתַּחְתּוֹנָה כֵן וְכוּ', כִּדְאִיתָא בְתוֹרַת כֹּהֲנִים. גְּמָרוֹ שֶׁל דָּבָר אֵין נְתִיצָה אֶלָּא בְּנֶגַע הַחוֹזֵר אַחַר חֲלִיצָה וְקִצּוּעַ וְטִיחָה, וְאֵין הַחוֹזֵר צָרִיךְ פִּשְׂיוֹן. וְסֵדֶר הַמִּקְרָאוֹת כָּךְ הוּא: וְאִם יָשׁוּב, וְנָתַץ, וְהַבָּא אֶל הַבַּיִת, וְהָאוֹכֵל בַּבַּיִת, וּבָא הַכֹּהֵן וְרָאָה וְהִנֵּה פָשָׂה, וְדִבֵּר הַכָּתוּב בָּעוֹמֵד בָּרִאשׁוֹן שֶׁנּוֹתֵן לוֹ שָׁבוּעַ שֵׁנִי לְהֶסְגֵּרוֹ, וּבְסוֹף שָׁבוּעַ שֵׁנִי לְהֶסְגֵּרוֹ בָּא וְרָאָהוּ שֶׁפָּשָׂה, וּמַה יַּעֲשֶֹה לוֹ? חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ, חָזַר, נוֹתֵץ, לֹא חָזַר, טָעוּן צִפֳּרִים; שֶׁאֵין בַּנְּגָעִים יוֹתֵר מִשְּׁלוֹשָׁה שָׁבוּעוֹת (עי' ספרא).
@46 **כל ימי הסגיר אתו.** וְלֹא יָמִים שֶׁקָּלַף אֶת נִגְעוֹ; יָכוֹל שֶׁאֲנִי מוֹצִיא הַמֻּחְלָט שֶׁקָּלַף אֶת נִגְעוֹ, תַּ"ל כָּל יְמֵי:
@46 **יטמא עד הערב.** מְלַמֵּד שֶׁאֵין מְטַמֵּא בְגָדִים; יָכוֹל אֲפִלוּ שָׁהָה בִכְדֵי אֲכִילַת פְּרָס, תַּ"ל וְהָאוֹכֵל בַּבַּיִת יְכַבֵּס אֶת בְּגָדָיו, אֵין לִי אֶלָּא אוֹכֵל, שׁוֹכֵב מִנַּיִן? תַּ"ל וְהַשּׁוֹכֵב, אֵין לִי אֶלָּא אוֹכֵל וְשׁוֹכֵב, לֹא אוֹכֵל וְלֹא שׁוֹכֵב מִנַּיִן? תַּ"ל **יכבס יכבס** רִבָּה; אִם כֵּן לָמָּה נֶאֱמַר אוֹכֵל וְשׁוֹכֵב? לִתֵּן שִׁעוּר לַשּׁוֹכֵב כְּדֵי אֲכִילַת פְּרָס (שם):
@48 **ואם בא יבא.** לְסוֹף שָׁבוּעַ שֵׁנִי:
@48 **וראה והנה לא פשה.** מִקְרָא זֶה בָּא לְלַמֵּד בָּעוֹמֵד בְּעֵינָיו בָּרִאשׁוֹן וּבַשֵּׁנִי וּמַה יַּעֲשֶׂה לוֹ, יָכוֹל יְטַהֲרֶנּוּ, כְּמַשְׁמָעוֹ שֶׁל מִקְרָא "וְטִהַר הַכֹּהֵן אֶת הַבַּיִת", תַּ"ל כִּי נִרְפָּא הַנָּגַע — לֹא טִהַרְתִּי אֶלָּא אֶת הָרָפוּי; וְאֵין רָפוּי אֶלָּא הַבַּיִת שֶׁהֻקְצָה וְהוּטַח וְלֹא חָזַר הַנֶּגַע — אֲבָל זֶה טָעוּן חֲלִיצָה וְקִצּוּי וְטִיחָה וְשָׁבוּעַ שְׁלִישִׁי; וְכֵן הַמִּקְרָא נִדְרָשׁ: וְאִם בֹּא יָבֹא בַשֵּׁנִי, וְרָאָה וְהִנֵּה לֹא פָשָׂה, יְטִיחֶנּוּ — וְאֵין טִיחָה בְּלֹא חִלּוּץ וְקִצּוּי — וְאַחֲרֵי הִטּוֹחַ אֶת הַבַּיִת וְטִהַר הַכֹּהֵן אֶת הַבַּיִת, אִם לֹא חָזַר לְסוֹף הַשָּׁבוּעַ, כִּי נִרְפָּא הַנָּגַע, וְאִם חָזַר, כְּבָר פֵּרֵשׁ עַל הַחוֹזֵר שֶׁטָּעוּן נְתִיצָה:
@57 **להורת ביום הטמא.** אֵיזֶה יוֹם מְטַהֲרוֹ וְאֵיזֶה יוֹם מְטַמְּאוֹ (עי' ספרא):
@59 **כי יהיה זב.** יָכוֹל זָב מִכָּל מָקוֹם יְהֵא טָמֵא, תַּ"ל מִבְּשָׂרוֹ, — וְלֹא כָל בְּשָׂרוֹ. אַחַר שֶׁחִלֵּק הַכָּתוּב בֵּין בָּשָׂר לְבָשָׂר זָכִיתִי לָדִין, טִמֵּא בְזָב וְטִמֵּא בְזָבָה, מַה זָּבָה מִמָּקוֹם שֶׁהִיא מִטַּמְּאָה טֻמְאָה קַלָּה — "נִדָּה" — מִטַּמְּאָה טֻמְאָה חֲמוּרָה — "זִיבָה" — אַף הַזָּב מִמָּקוֹם שֶׁמִּטַּמֵּא טֻמְאָה קַלָּה — "קֶרִי" — מִטַּמֵּא טֻמְאָה חֲמוּרָה — "זִיבָה" (שם):
@59 **זובו טמא.** לִמֵּד עַל הַטִּפָּה שֶׁהִיא מְטַמְּאָה; זוֹב דּוֹמֶה לְמֵי בָצֵק שֶׁל שְׂעוֹרִין, וְדָחוּי, וְדּוֹמֶה לְלֹבֶן בֵּיצָה הַמּוּזֶרֶת, שִׁכְבַת זֶרַע קָשׁוּר, כְּלֹבֶן בֵּיצָה שֶׁאֵינָהּ מוּזֶרֶת:
@60 **רר.** לְשׁוֹן רִיר — שֶׁזָּב בְּשָׂרוֹ אֶת זוֹבוֹ כְּמוֹ רִיר, שֶׁיּוֹצֵא צָלוּל:
@60 **או החתים.** שֶׁיּוֹצֵא עָב, וְסוֹתֵם אֶת פִּי הָאַמָּה, וְנִסְתָּם בְּשָׂרוֹ מִטִּפַּת זוֹבוֹ, זֶהוּ פְּשׁוּטוֹ; וּמִדְרָשׁוֹ: מָנָה הַכָּתוּב הָרִאשׁוֹן רְאִיּוֹת שְׁתַּיִם וּקְרָאוֹ טָמֵא, שֶׁנֶּאֱמַר זָב מִבְּשָׂרוֹ זוֹבוֹ טָמֵא הוּא, וּמָנָה הַכָּתוּב הַשֵּׁנִי רְאִיּוֹת שָׁלֹשׁ וּקְרָאוֹ טָמֵא, שֶׁנֶּאֱמַר טֻמְאָתוֹ בְּזוֹבוֹ רָר בְּשָׂרוֹ אֶת זוֹבוֹ אוֹ הֶחְתִּים בְּשָׂרוֹ מִזּוֹבוֹ טֻמְאָתוֹ הִוא, הָא כֵיצַד? שְׁתַּיִם לְטֻמְאָה, וְהַשְּׁלִישִׁית מַזְקִיקַתּוּ לְקָרְבָּן (נדה מ"ג: מגילה ח.):
@61 **כל המשכב.** הָרָאוּי לְמִשְׁכָּב; יָכוֹל אֲפִלּוּ מְיֻחָד לִמְלָאכָה אַחֶרֶת, תַּ"ל אֲשֶׁר יִשְׁכַּב — אֲשֶׁר שָׁכַב לֹא נֶאֱמַר אֶלָּא אֲשֶׁר יִשְׁכַּב — הַמְיֻחָד תָּמִיד לְכָךְ, יָצָא זֶה שֶׁאוֹמְרִין לוֹ "עֲמֹד וְנַעֲשֶׂה מְלַאכְתֵּנוּ":
@61 **אשר ישב.** יָשַׁב לֹא נֶאֱמַר אֶלָּא אֲשֶׁר יֵשֵׁב עָלָיו, בַּמְיֻחָד תָּמִיד לְכָךְ (שבת נ"ט):
@62 **ואיש אשר יגע במשכבו.** לִמֵּד עַל הַמִּשְׁכָּב שֶׁחָמוּר מִן הַמַּגָּע, שֶׁזֶּה נַעֲשֶׂה אַב הַטֻּמְאָה לְטַמֵּא אָדָם לְטַמֵּא בְגָדִים, וְהַמַּגָּע שֶׁאֵינוֹ מִשְׁכָּב אֵינוֹ אֶלָּא וְלַד הַטֻּמְאָה, וְאֵינוֹ מְטַמֵּא אֶלָּא אֳכָלִין וּמַשְׁקִין (עי' ספרא):
@63 **והישב על הכלי.** אֲפִלּוּ לֹא נָגַע — אֲפִלוּ עֲשָֹרָה כֵלִים זֶה עַל זֶה — כֻּלָּן מְטַמְּאִין מִשּׁוּם מוֹשָׁב, וְכֵן בְּמִשְׁכָּב:
@65 **וכי ירק הזב בטהור.** וְנָגַע בּוֹ אוֹ נְשָׂאוֹ, שֶׁהָרֹק מְטַמֵּא בְמַשָּׂא (עי' נדה נ"ה):
@66 **וכל המרכב.** אַעַ"פִּ שֶׁלֹּא יָשַׁב עָלָיו, כְּגוֹן הַתְּפוּס שֶׁל סְרָגָא, שֶׁקּוֹרִין ארצו"ן, טָמֵא מִשּׁוּם מֶרְכָּב, וְהָאֻכָּף שֶׁקּוֹרִין סל"ויש טָמֵא טֻמְאַת מוֹשָׁב (עירובין כ"ז):
@67 **וכל הנגע בכל אשר יהיה תחתיו.** שֶׁל זָב; בָּא וְלִמֵּד עַל הַמֶּרְכָּב שֶׁיְּהֵא הַנּוֹגֵעַ בּוֹ טָמֵא וְאֵין טָעוּן כִּבּוּס בְּגָדִים, וְהוּא חֹמֶר בַּמִּשְׁכָּב מִבַּמֶּרְכָּב:
@67 **והנושא אותם.** אֶת כָּל הָאָמוּר בְּעִנְיַן הַזָּב — זוֹבוֹ וְרֻקּוֹ וְשִׁכְבַת זַרְעוֹ וּמֵימֵי רַגְלָיו וְהַמִּשְׁכָּב וְהַמֶּרְכָּב — מַשָּׂאָן מְטַמֵּא אָדָם לְטַמֵּא בְגָדִים (עי' ספרא):
@68 **וידיו לא שטף במים.** בְּעוֹד שֶׁלֹּא טָבַל מִטֻּמְאָתוֹ, וַאֲפִלּוּ פָסַק מִזּוֹבוֹ וְסָפַר שִׁבְעָה וּמְחֻסָּר טְבִילָה, מְטַמֵּא בְכָל טֻמְאוֹתָיו, וְזֶה שֶׁהוֹצִיא הַכָּתוּב טְבִילַת גוּפוֹ שֶׁל זָב בִּלְשׁוֹן שְׁטִיפַת יָדַיִם, לְלַמֶּדְךָ שֶׁאֵין בֵּית הַסְּתָרִים טָעוּן בִּיאַת מַיִם, אֶלָּא אֵבֶר הַגָּלוּי כְּמוֹ הַיָּדַיִם (ספרא):
@69 **וכלי חרש אשר יגע בו הזב.** יָכוֹל אֲפִלּוּ נָגַע בּוֹ מֵאֲחוֹרָיו וְכוּ', כִּדְאִיתָא בְתוֹרַת כֹּהֲנִים עַד "מַגָּעוֹ שֶׁהוּא כְכֻלּוֹ הֱוֵי אוֹמֵר זֶה הֶסֵּטוֹ":
@70 **וכי יטהר.** כְּשֶׁיִּפְסֹק (שם):
@70 **שבעת ימים לטהרתו.** שִׁבְעַת יָמִים טְהוֹרִים מִטֻּמְאַת זִיבָה, שֶׁלֹּא יִרְאֶה זוֹב, וְכֻלָּן רְצוּפִין (ספרא):
@75 **ורחצו במים.** גְּזֵרַת מֶלֶךְ הִיא שֶׁתִּטְמָא הָאִשָּׁה בְּבִיאָה; וְאֵין הַטַּעַם מִשּׁוּם נוֹגֵעַ בְּשִׁכְבַת זֶרַע, שֶׁהֲרֵי מַגַּע בֵּית הַסְּתָרִים הוּא (נדה מ"א:):
@76 **כי תהיה זבה.** יָכוֹל מֵאֶחָד מִכָּל אֵבָרֶיהָ, תַּ"ל וְהִיא גִּלְּתָה אֶת מְקוֹר דָּמֶיהָ — אֵין דָּם מְטַמֵּא אֶלָּא הַבָּא מִן הַמָּקוֹר:
@76 **דם יהיה זבה בבשרה.** אֵין זוֹבָהּ קָרוּי זוֹב לְטַמֵּא אֶלָּא אִם כֵּן הוּא אָדֹם (שם י"ט):
@76 **בנדתה.** כְּמוֹ וּמִתֵּבֵל יְנִדֻּהוּ (איוב י"ח) — שֶׁהִיא מְנֻדָּה מִמַּגַּע כָּל אָדָם:
@76 **תהיה בנדתה.** אֲפִלּוּ לֹא רָאֲתָה אֶלָּא רְאִיָּה רִאשׁוֹנָה (ספרא):
@80 **ואם על המשכב הוא.** הַשּׁוֹכֵב אוֹ הַיּוֹשֵׁב עַל מִשְׁכָּבָהּ אוֹ עַל מוֹשָׁבָהּ אֲפִלּוּ לֹא נָגַע בָּהּ, אַף הוּא בְּדַת טֻמְאָה הָאֲמוּרָה בַּמִקְרָא הָעֶלְיוֹן, שֶׁטָּעוּן כִּבּוּס בְּגָדִים:
@80 **על הכלי.** לְרַבּוֹת אֶת הַמֶּרְכָּב:
@80 **בנגעו בו.** אֵינוֹ מְדַבֵּר אֶלָּא עַל הַמֶּרְכָּב שֶׁנִּתְרַבָּה מֵ"עַל הַכְּלִי":
@80 **בנגעו בו יטמא.** וְאֵינוֹ טָעוּן כִּבּוּס בְּגָדִים, שֶׁהַמֶּרְכָּב אֵין מַגָּעוֹ מְטַמֵּא אָדָם לְטַמֵּא בְגָדִים (כלים פכ"ג):
@81 **ותהי נדתה עליו.** יָכוֹל יַעֲלֶה לְרַגְלָהּ — שֶׁאִם בָּא עָלֶיהָ בַחֲמִישִׁי לְנִדָּתָהּ לֹא יִטְמָא אֶלָּא שְׁלוֹשָׁה יָמִים כְּמוֹתָהּ — תַּ"ל וְטָמֵא שִׁבְעַת יָמִים, וּמַה תַּ"ל וּתְהִי נִדָּתָהּ עָלָיו? מַה הִיא מְטַמְּאָה אָדָם וּכְלֵי חֶרֶס, אַף הוּא מְטַמֵּא אָדָם וּכְלֵי חֶרֶס (ספרא; נדה ל"ג):
@82 **ימים רבים.** שְׁלֹשָׁה יָמִים (ספרא):
@82 **בלא עת נדתה.** אַחַר שֶׁיָּצְאוּ שִׁבְעַת יְמֵי נִדָּתָהּ:
@82 **או כי תזוב.** אֶת שְׁלֹשֶׁת הַיָּמִים הַלָּלוּ:
@82 **על נדתה.** מֻפְלָג מִנִּדָּתָהּ יוֹם אֶחָד, זוֹ הִיא זָבָה, וּמִשְׁפָּטָהּ חָרוּץ בְּפָרָשָׁה זוֹ, וְלֹא כְּדַת הַנִּדָּה, שֶׁזּוֹ טְעוּנָה סְפִירַת שִׁבְעָה נְקִיִּים וְקָרְבָּן, וְהַנִּדָּה אֵינָהּ טְעוּנָה סְפִירַת נְקִיִּים, אֶלָּא שִׁבְעַת יָמִים תִּהְיֶה בְנִדָּתָהּ בֵּין רוֹאָה בֵּין שֶׁאֵינָהּ רוֹאָה. וְדָרְשׁוּ בְּפָרָשָׁה זוֹ י"א יוֹם בֵּין סוֹף נִדָּה לִתְחִלַּת נִדָּה, שֶׁכָּל שְׁלֹשֶׁת רְצוּפִין שֶׁתִּרְאֶה בְאַחַד עָשָׂר יוֹם הַלָּלוּ תְּהֵא זָבָה:
@88 **והזרתם.** אֵין נְזִירָה אֶלָּא פְרִישָׁה וְכֵן נָזֹרוּ אָחוֹר (ישעיהו א'), וְכֵן נְזִיר אֶחָיו (בראשית מ"ט):
@88 **ולא ימתו בטמאתם.** הֲרֵי הִכָּרֵת שֶׁל מְטַמֵּא מִקְדָּשׁ קָרוּי מִיתָה:
@89 **זאת תורת הזב.** בַּעַל רְאִיָּה אַחַת, וּמַהוּ תוֹרָתוֹ?
@89 **ואשר תצא ממנו שכבת זרע** — הֲרֵי הוּא כְּבַעַל קֶרִי, טָמֵא טֻמְאַת עֶרֶב:
@90 **והזב את זובו.** בַּעַל שְׁתֵּי רְאִיּוֹת, וּבַעַל שָׁלוֹשׁ רְאִיּוֹת, שֶׁתּוֹרָתָן מְפֹרֶשֶׁת לְמַעְלָה:

@2 **וְהוּבָא אֶל הַכֹּהֵן** יֹאמַר שֶׁתִּהְיֶה זֹאת תּוֹרַת הַמְּצֹרָע בַּיּוֹם שֶׁיִּרְצֶה לְהִטָּהֵר, שֶׁיּוּבָא אֶל הַכֹּהֵן, כִּי אֵין לוֹ טַהֲרָה לְעוֹלָם אֶלָּא עַל פִּיו. וְאח"כ פֵּרֵשׁ כִּי הַכֹּהֵן יֵצֵא אֶל מְקוֹם מוֹשָׁבוֹ מִחוּץ לַמַּחֲנֶה וְהוּא לֹא יָבֹא אֵלָיו אע"פ שֶׁנִּתְרַפֵּא. וּמִדְרָשׁוֹ בְּתוֹרַת כֹּהֲנִים (פרשה א ג), "וְהוּבָא אֶל הַכֹּהֵן" שֶׁלֹּא יִשְׁהֶה. וְאִם כֵּן יֹאמַר כִּי בַּיּוֹם שֶׁיִּטְהַר שֶׁיִּתְרַפֵּא מִנִּגְעוֹ יוּבָא עַל כָּרְחוֹ אֶל הַכֹּהֵן. וְכֵן "וְכִי יִטְהַר הַזָּב מִזּוֹבוֹ" (ויקרא ט"ו:י"ג), "וְאִם טָהֲרָה מִזּוֹבָהּ" (שם טו כח), כְּשֶׁיִּפָּסְקוּ וְיִהְיוּ מְנֻקִּים מִמֶּנּוּ כַּאֲשֶׁר פֵּרַשְׁתִּי (רמב"ן על ויקרא ט"ו:י"א), וְהוּא הַנָּכוֹן:
@4 **חַיּוֹת** פְּרָט לִטְרֵפוֹת. **טְהוֹרוֹת** פְּרָט לְעוֹף טָמֵא. לְפִי שֶׁהַנְּגָעִים בָּאִים עַל לָשׁוֹן הָרַע שֶׁהוּא מַעֲשֵׂה פָּטִיט, לְפִיכָךְ הֻצְרְכוּ בְּטַהֲרָתוֹ צִפֳּרִים שֶׁמְּפַטְפְּטִין תָּמִיד בְּצִפְצוּף קוֹל, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ד:ד'). וּמִפְּנֵי שֶׁאָמַר "טְהוֹרוֹת פְּרָט לְעוֹף טָמֵא", נִלְמַד שֶׁאֵין הַצִּפֳּרִים מִין טָהוֹר יָדוּעַ, אֲבָל הוּא שֵׁם כּוֹלֵל כָּל הָעוֹפוֹת. אִם כֵּן מַהוּ הַפִּטְפּוּט הַזֶּה שֶׁמָּצְאוּ לָהֶם, כִּי עוֹפוֹת רַבִּים אֵין בָּהֶם פּוֹצֶה פֶּה וּמְצַפְצֵף. וְעוֹד כִּי מִדְרַשׁ "חַיּוֹת פְּרָט לִטְרֵפוֹת" יָבֹא בְּמַחְלֹקֶת, וּלְמַאן דְּאָמַר טְרֵפָה חַיָּה אֵינוֹ כֵן. וּבְתוֹרַת כֹּהֲנִים (פרשה א יב), "חַיּוֹת" - לֹא שְׁחוּטוֹת. "טְהוֹרוֹת" - לֹא טְמֵאוֹת. "טְהוֹרוֹת" - לֹא טְרֵפוֹת. וּבַעֲלֵי הַפְּשָׁט אוֹמְרִים כִּי כָל עוֹף יִקָּרֵא צִפּוֹר, מִמַּה שֶׁאָמַר "צִפּוֹר שָׁמַיִם וּדְגֵי הַיָּם" (תהלים ח ט), "כֹּל צִפּוֹר כָּל כָּנָף" (בראשית ז יד), "בֶּן אָדָם אֱמֹר לְצִפּוֹר כָּל כָּנָף" (יחזקאל לט יז), וְכֵן "וְאֶת הַצִּפֹּר לֹא בָתָר" (בראשית טו י) עַל תּוֹרִים וּבְנֵי יוֹנָה. וְהַנָּכוֹן בְּעֵינַי שֶׁשֵּׁם צִפּוֹר כְּלָל לָעוֹפוֹת הַקְּטַנִּים הַמַּשְׁכִּימִים בַּבֹּקֶר לְצַפְצֵף וּלְשׁוֹרֵר, מִלְּשׁוֹן אֲרַמִּית "צַפְרָא", וְכֵן "יָשׁוּב וְיִצְפֹּר" (שופטים ז ג), יַשְׁכִּים בַּבֹּקֶר. אָמַר "צִפּוֹר שָׁמַיִם" עֲלֵיהֶם כִּי הֵם לְרֻבָּם יַגְבִּיהוּ לָעוּף בַּשָּׁמַיִם; וְ"כֹל צִפּוֹר כָּל כָּנָף" (בראשית ז יד) שְׁנֵי מִינִין, כָּל הַקְּטַנִּים וְכָל הַגְּדוֹלִים; "כִּי יִקָּרֵא קַן צִפּוֹר לְפָנֶיךָ" (דברים כב ו), הֵם הַקְּטַנִּים שֶׁהֵן רַבִּים, שֶׁאֲפִלּוּ בִּקְטַנֵּיהֶם יָחוּס; וְכֵן "אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ" (תהלים קד יז), כִּי הֵם הַשּׁוֹכְנִים בְּעַנְפֵי אַרְזֵי הַלְּבָנוֹן; "אֱמֹר לְצִפּוֹר כָּל כָּנָף" (יחזקאל לט יז), שֶׁיִּתְאַסְּפוּ אֲפִלּוּ הַקְּטַנִּים עֲלֵיהֶם, כִּי הַטּוֹרְפִים יָבֹאוּ מֵעַצְמָם; וְכֵן "הַתְשַׂחֶק בּוֹ כַּצִּפּוֹר וְתִקְשְׁרֶנּוּ לְנַעֲרוֹתֶיךָ" (איוב מ כט), כִּי דֶּרֶךְ הַנְּעָרִים לְשַׂחֵק בָּעוֹף הַקָּטָן. וּלְשׁוֹן חֲכָמִים כָּךְ הוּא, כָּל שֶׁיֵּשׁ בְּיָדוֹ מַקֵּל אוֹ צִפּוֹר (עבודה זרה מ), הָאוֹרֵג מִשְּׂעַר הַנָּזִיר כִּמְלֹא הַסִּיט בְּבֶגֶד בְּצִפַּרְתָּא (תמורה לד), וְאָמְרוּ צִפֹּרֶת כְּרָמִים (שבת צ), וְאָמְרוּ בְּשַׂר צִפֳּרִים מַחְזִירִין הַחוֹלֶה לְחָלְיוֹ (ברכות נז). וְאָמַר בַּכָּתוּב (דברים יד יא) "כָּל צִפּוֹר טְהֹרָה תֹּאכֵלוּ", עַל הַמִּינִין הָרַבִּים הָהֵם, וְנִתְרַבָּה שֶׁל מְצֹרָע מִ"כָּל" וְאָמַר (שם פסוק יב), "וְזֶה אֲשֶׁר לֹא תֹאכְלוּ מֵהֶם", כְּאוֹמֵר וְאֵלֶּה אֲשֶׁר לֹא תֹּאכְלוּ מִבְּשָׂרָם, וּלְכָךְ דָּרְשׁוּ "טְהוֹרוֹת לֹא טְמֵאוֹת". וּמִכָּל מָקוֹם כֻּלָּם בַּעֲלֵי פִּטְפּוּט הֵם. וְכֵן גַּם כֵּן "גַּם צִפּוֹר מָצְאָה בַיִת וּדְרוֹר קֵן לָהּ" (תהלים פד ד), כָּךְ נִרְאֶה שֶׁאֵינוֹ שֵׁם כּוֹלֵל הָעוֹפוֹת כֻּלָּם, וְכֵן "אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ חֲסִידָה בְּרוֹשִׁים בֵּיתָהּ" (שם קד יז). וְהַנִּרְאֶה מִדִּבְרֵי רַבּוֹתֵינוּ שֶׁכָּל עוֹפוֹת טְהוֹרִים נִקְרָאִים "צִפּוֹר", אֲבָל מִצְוָתוֹ שֶׁל מְצֹרָע בְּצִפֳּרֵי דְּרוֹר, דְּתַנְיָא בְּת"כ (פרק ה יד), "וְשִׁלַּח אֶת הַצִּפֹּר הַחַיָּה אֶל מִחוּץ לָעִיר אֶל פְּנֵי הַשָּׂדֶה" (ויקרא י"ד:נ"ג), רַבִּי יוֹסֵי הַגְּלִילִי אוֹמֵר, צִפּוֹר שֶׁחַיָּה חוּץ לְכָל עִיר, וְאֵי זוֹ, זֶה דְּרוֹר. וּמִן הַמִּדְרָשׁ הַזֶּה הִזְכִּירוּ הַפִּטְפּוּט. וְיִתָּכֵן שֶׁאֵינוֹ אֶלָּא לְמִצְוָה, וְדִיעֲבַד כֻּלָּם כְּשֵׁרִין בּוֹ, וּלְפִיכָךְ הֻצְרְכוּ בְּת"כ (כאן) לְמַעֵט טְמֵאוֹת. וְכֵן שָׁנִינוּ בַּמִּשְׁנָה מַסֶּכֶת נְגָעִים (פי"ד מ"א), וּמֵבִיא שְׁתֵּי צִפֳּרִים דְּרוֹר. וְשָׁנוּ עוֹד שָׁם (משנה ה), שְׁתֵּי צִפֳּרִים מִצְוָתָן שֶׁיִּהְיוּ שָׁווֹת בְּמַרְאֶה בְּקוֹמָה וּבְדָמִים וּלְקִיחָתָן כְּאַחַת, אע"פ שֶׁאֵינָן שָׁווֹת כְּשֵׁרוֹת. שָׁחַט אַחַת מֵהֶן וְנִמְצֵאת שֶׁלֹּא דְּרוֹר, יִקַּח זוּג לַשְּׁנִיָּה. וְהַטַּעַם בָּזֶה, שֶׁאַף עַל פִּי שֶׁבְּדִיעֲבַד כֻּלָּן כְּשֵׁרוֹת, כְּשֶׁהֵן שְׁנֵי מִינִים פְּסוּלוֹת. וּבְפֶרֶק אֵלּוּ טְרֵפוֹת (חולין סב) אָמְרוּ, עוֹף הַמְסָרֵט כָּשֵׁר לְטַהֵר בּוֹ אֶת הַמְּצֹרָע, וְזוֹ הִיא סְנוּנִית לְבָנָה שֶׁנֶּחְלְקוּ בָּהּ רַבִּי אֱלִיעֶזֶר וַחֲכָמִים. וּמִכָּאן שֶׁאֵין צִפֳּרֵי הַמְּצֹרָע מִין אֶחָד בִּלְבַד, וְשֶׁאֵין מְטַהֲרִין בְּכָל עוֹף טָהוֹר, אֲבָל מִצְוָתוֹ בְּכָל עוֹף דְּרוֹר, כְּלוֹמַר שֶׁדָּרָה בַּבַּיִת כְּבַשָּׂדֶה. וּלְפִיכָךְ אָמְרוּ בִּסְנוּנִית, דְּכֵיוָן שֶׁהִיא טְהוֹרָה לְדַעַת חֲכָמִים כְּשֵׁרָה לְטַהֵר בָּהּ שֶׁהִיא בִּכְלַל דְּרוֹר. וּמִכָּל מָקוֹם כָּל הַטְּהוֹרִין כְּשֵׁרִים בְּדִיעֲבַד, שֶׁכֻּלָּן בִּכְלַל שְׁתֵּי צִפֳּרִים טְהוֹרוֹת. וְשָׁנוּ בְּסִפְרֵי (ראה קג), אָמַר רַבִּי יֹאשִׁיָּה, כָּל מָקוֹם שֶׁנֶּאֱמַר "צִפּוֹר", בִּטְהוֹרָה הַכָּתוּב מְדַבֵּר. וְאָמַר רַבִּי יִצְחָק, עוֹף טָהוֹר נִקְרָא "עוֹף" וְנִקְרָא "צִפּוֹר", וְטָמֵא לֹא נִקְרָא אֶלָּא "עוֹף". וְכָךְ הִזְכִּירוּ בַּגְּמָרָא בְּפֶרֶק שִׁלּוּחַ הַקֵּן (חולין קלט), וְשָׁם הֶעֱלוּ (קמ) כִּי "חַיּוֹת" - שֶׁחַיִּין רָאשֵׁי אֵבָרִים שֶׁלָּהֶם, לְמַעוֹטֵי מְחֻסְּרוֹת אֵבָר. וְכֵן הַטְּרֵפוֹת פְּסוּלוֹת בָּהֶן. וְדָרְשׁוּ "טְהוֹרוֹת" - לְמַעֵט אֲסוּרוֹת, כְּגוֹן צִפֳּרֵי עִיר הַנִּדַּחַת וְעוֹף שֶׁהָרַג אֶת הַנֶּפֶשׁ וְהַחִלּוּפִין בַּע"ז. וּמִדְרָשָׁם זֶה שָׁם מִן הַלָּשׁוֹן עַצְמוֹ, שֶׁאֵין צִפּוֹר אֶלָּא עוֹף טָהוֹר, וּמַשְׁמַע מִכָּאן שֶׁכָּל עוֹף טָהוֹר בִּכְלַל צִפּוֹר. וְרָאִיתִי עוֹד בַּיְּרוּשַׁלְמִי בְּמַסֶּכֶת נָזִיר (פ"א ה"א) שֶׁאָמְרוּ, וְכִי נָזִיר טָמֵא צִפֳּרִים הוּא מֵבִיא, תּוֹרִים וּבְנֵי יוֹנָה הוּא מֵבִיא, אִית תַּנַּיֵי תָּנֵי, כָּל עוֹף טָהוֹר קָרוּי צִפֳּרִים, אִית תַּנַּיֵי תָּנֵי, כָּל הָעוֹפוֹת בֵּין טָמֵא וּבֵין טָהוֹר קָרוּי צִפֳּרִים. וְהִנֵּה נִשְׁאַר בְּיָדֵינוּ מִמֶּנּוּ מַחְלֹקֶת. וּמִכָּל מָקוֹם יִתָּכֵן שֶׁיִּהְיֶה הַשֵּׁם בַּקְּטַנִּים בִּלְבַד. וּבַגְּמָרָא כָּךְ הוּא נִרְאֶה, מִמַּה שֶׁאָמְרוּ בְּמַסֶּכֶת סוֹטָה (סוטה ט"ז), הָבֵא מַיִם שֶׁדַּם צִפּוֹר נִכָּר בָּהֶם, וְכַמָּה הֵם, רְבִיעִית. וְשָׁאֲלוּ, גְּדוֹלָה שֶׁדּוֹחָה אֶת הַמַּיִם, קְטַנָּה וְנִדְחֵת מִפְּנֵי הַמַּיִם, מַהוּ, וּפֵרְשׁוּ, כָּל שִׁעוּרֵי חֲכָמִים כָּךְ הֵם, בְּצִפּוֹר דְּרוֹר שִׁעֲרוּ חֲכָמִים, אֵין לְךָ גְּדוֹלָה שֶׁדּוֹחָה אֶת הַמַּיִם וְאֵין לְךָ קְטַנָּה שֶׁנִּדְחֵית מִפְּנֵי הַמַּיִם. וְאִלּוּ הָיָה כָּל עוֹף טָהוֹר כָּשֵׁר בּוֹ, הָיָה מֵהֶם מִי שֶׁדָּמוֹ דּוֹחֶה כַּמָּה לֻגִּין. וְאוּלַי אָמְרוּ כֵן בְּצִפּוֹר דְּרוֹר שֶׁהוּא מִצְוָה לְכַתְּחִלָּה, מִמִּדְרָשׁוֹ שֶׁל רַ' יוֹסֵי הַגְּלִילִי. וּכְבָר הִזְכִּירוּ בַּגְּמָרָא (שבועות כט), וְדִלְמָא צִפּוֹרָא רַבָּא חֲזָא וְאַסֵּק שְׁמֵהּ גָּמָל. וְהַנָּכוֹן שֶׁיַּעֲלֶה מִכָּל זֶה הוּא שֶׁנֹּאמַר שֶׁכָּל צִפּוֹר שֶׁאֵינוֹ דְּרוֹר פָּסוּל אֲפִילּוּ בְּדִיעֲבַד, מִן הַמִּדְרָשׁ הַזֶּה שֶׁלֹּא שָׁנוּ בְּמִשְׁנָתֵנוּ (נגעים יד א) מִצְוָתָן שֶׁיְּהוּ דְּרוֹר, אע"פ שֶׁאֵינָן דְּרוֹר כְּשֵׁרוֹת - כְּמוֹ שֶׁשָּׁנִינוּ בְּשָׁווֹת (שם יד ה). וְכָל הַדְּרוֹרִים בַּעֲלֵי פִּטְפּוּט הֵם. וּמַה שֶׁאָמְרוּ בְּת"כ "לֹא טְמֵאוֹת", מִפְּנֵי שֶׁיֵּשׁ אַף בַּטְּמֵאִין מִינִין שֶׁהֵם דְּרוֹר, כְּגוֹן הַסְּנוּנִית לְרַבִּי אֱלִיעֶזֶר. אוֹ יִהְיֶה פֵּרוּשׁוֹ לְמַעֵט טְמֵאוֹת לְךָ, שֶׁהֵן הָאֲסוּרוֹת וְהַטְּרֵפוֹת, כְּמוֹ שֶׁהֶעֱלוּ בַּגְּמָרָא בְּפֶרֶק שִׁלּוּחַ הַקֵּן (חולין קמ). וְזֶהוּ הֶהָגוּן בְּעֵינַי. וּבַהַגָּדָה דְּרַבָּה (ויקרא רבה טז ז) אָמַר רַבִּי יְהוּדָה בְּרַבִּי סִימוֹן, אִלֵּן צִפְּרַיָּא קוֹלָנִין, זֶה הָאוֹמֵר לָשׁוֹן הָרַע. אָמַר הקב"ה, יָבֹא קוֹל וִיכַפֵּר עַל קוֹל. וְר' יְהוֹשֻׁעַ בֶּן לֵוִי אָמַר, צִפֳּרִים צִפֳּרֵי דְּרוֹר, שֶׁאָכְלָה מִפִּתּוֹ וְשָׁתַת מִן מֵימָיו. וַהֲלֹא דְּבָרִים קַל וָחֹמֶר וְכוּ':
@4 **וְעֵץ אֶרֶז וּשְׁנִי תוֹלַעַת וְאֵזֹב** אָמַר ר"א (אבן עזרא על ויקרא י"ד:ד') הוּא הַגָּדוֹל וְהַקָּטָן בְּמִינֵי הַצְּמָחִים, וְהָעֵד מִדִּבְרֵי חָכְמַת שְׁלֹמֹה (מלכים א ה יג). וְהִנֵּה הַמְּצֹרָע וְתוֹרַת הַבַּיִת הַמְּנֻגָּע וְטֻמְאַת הַמֵּת קְרוֹבִים, וְהִנֵּה הֵם כִּדְמוּת פֶּסַח מִצְרַיִם. וְטַעַם "עַל פְּנֵי הַשָּׂדֶה" (ויקרא י"ד:ז'), מָקוֹם אֲשֶׁר אֵין שָׁם יִשּׁוּב, שֶׁלֹּא תִּדְבַּק הַצָּרַעַת. וּבְת"כ (פרשה ב ה) אָמְרוּ, "עַל פְּנֵי הַשָּׂדֶה", שֶׁלֹּא יַעֲמֹד בְּיָפוֹ וִישַׁלְּחֶנָּה לַיָּם, שֶׁלֹּא יַעֲמוֹד בִּגְבַת וִישַׁלְּחֶנָּה לַמִּדְבָּר. וְאִם כֵּן יִהְיֶה הַטַּעַם כְּסוֹד הַשָּׂעִיר הַמִּשְׁתַּלֵּחַ, וְשָׁם יִשְׁתַּלַּח לַעֲזָאזֵל הַמִּדְבָּרָה וְכָאן לְפוֹרְחוֹת הַשָּׂדֶה. וְעוֹד אֲפָרֵשׁ זֶה (רמב"ן על ויקרא ט"ז:ח') בע"ה:
@9 **אֶת כָּל שְׂעָרוֹ** כְּלָל וּפְרָט וּכְלָל, לְהָבִיא כָּל מְקוֹם כִּנּוּס שֵׂעָר הַנִּרְאֶה, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא י"ד:ט'). אֲבָל בְּת"כ (פרק ב ב ג) "וְגִלַּח אֶת שְׂעָרוֹ", יָכוֹל אַף בֵּית הַסְּתָרִים, תַּלְמוּד לוֹמַר "גַּבּוֹת עֵינָיו", מַה גַּבּוֹת עֵינָיו בְּנִרְאֶה אַף כָּל שְׂעָרוֹ בְּנִרְאֶה, פְּרָט לְבֵית הַסְּתָרִים. אִי מַה גַּבּוֹת עֵינָיו מָקוֹם כִּנּוּס שֵׂעָר בְּנִרְאֶה, אַף כָּל מָקוֹם כִּנּוּס שֵׂעָר בְּנִרְאֶה, מִנַּיִן כִּנּוּס שֵׂעָר בְּשֶׁאֵינוֹ נִרְאֶה, פִּזּוּר שֵׂעָר בְּשֶׁאֵינוֹ נִרְאֶה, ת"ל "אֶת כָּל שְׂעָרוֹ יְגַלֵּחַ". אֲבָל הָרַב תָּפַס מִדְרָשׁוֹ שֶׁל רַבִּי יִשְׁמָעֵאל, מַאי הֵבִיא, שְׂעַר הָרַגְלַיִם, וּמַאי הוֹצִיא, דְּבֵית הַשֶּׁחִי וּדְכוּלֵּי גּוּפֵהּ. אֲבָל בְּכָאן הֲלָכָה מְגַלֵּחַ כִּדְלַעַת, אוֹ מִפְּנֵי שֶׁהֲלָכָה עוֹקֶבֶת אֶת הַמִּדְרָשׁ אוֹ מִפְּנֵי שֶׁהֲלָכָה כְּדִבְרֵי רַבִּי עֲקִיבָא, וְרַבִּי דְּכֻלֵּי גּוּפֵהּ, וּמִעֵט שֶׁבְּתוֹךְ הַחֹטֶם בִּלְבַד. וְכֵן שָׁנִינוּ בְּמִשְׁנָתֵנוּ (נגעים פי"ד מ"ב), וְהֶעֱבִיר תַּעַר עַל כָּל בְּשָׂרוֹ, וּמְפֹרָשׁ בְּפֶרֶק שֵׁנִי דְּסוֹטָה (טז):
@10 **יִקַּח שְׁנֵי כְבָשִׂים תְּמִימִים וְכַבְשָׂה אַחַת** לֹא פֵּרֵשׁ הַכָּתוּב מַה יַעֲשֶׂה בִּשְׁנֵי הַכְּבָשִׂים וְכַבְשָׂה, אֲבָל הִזְכִּיר בַּכֶּבֶשׁ הָאֶחָד שֶׁיַּקְרִיב אוֹתוֹ לְאָשָׁם (ויקרא י"ד:י"ב), וְהִזְכִּיר שֶׁיַּעֲשֶׂה הַחַטָּאת וְאַחַר יִשְׁחַט הָעוֹלָה (ויקרא י"ד:י"ט). וְזֶה בַּעֲבוּר שֶׁכְּבָר הִזְכִּיר בְּפָרָשַׁת וַיִּקְרָא (ה-ו) בְּחַטָּאת שֶׁתִּהְיֶה נְקֵבָה, וְהִזְכִּיר בְּכָל עוֹלָה (שם א-ג ועוד) שֶׁהוּא זָכָר, לְכָךְ לֹא הֻצְרַךְ לְהַאֲרִיךְ, כִּי בְּיָדוּעַ שֶׁהַכֶּבֶשׂ הַשֵּׁנִי יִהְיֶה הָעוֹלָה וְהַכַּבְשָׂה הִיא הַחַטָּאת:
@18 **יִתֵּן עַל רֹאשׁ הַמִּטַּהֵר וְכִפֶּר עָלָיו הַכֹּהֵן לִפְנֵי ה'** בְּמַעֲשֵׂה דַּם הָאָשָׁם וְהַשֶּׁמֶן תִּהְיֶה הַכַּפָּרָה הַזֹּאת. וְכֵן "לְכַפֵּר עָלָיו לִפְנֵי ה'" (ויקרא י"ד:כ"ט). וּבְתוֹרַת כֹּהֲנִים (פרק ג יב), "וְהַנּוֹתָר בַּשֶּׁמֶן אֲשֶׁר עַל כַּף הַכֹּהֵן יִתֵּן עַל רֹאשׁ הַמִּטַּהֵר וְכִפֶּר" - אִם נָתַן כִּפֵּר, וְאִם לֹא נָתַן לֹא כִּפֵּר, דִּבְרֵי רַבִּי עֲקִיבָא. רַבִּי יוֹחָנָן בֶּן נוּרִי אָמַר, שְׁיָרֵי מִצְוָה הֵם, בֵּין שֶׁנָּתַן בֵּין שֶׁלֹּא נָתַן - כִּפֵּר. וְא"כ עַל דַּעַת ר' יוֹחָנָן בֶּן נוּרִי יִהְיֶה "וְכִפֶּר עָלָיו" עַל הָאָשָׁם. וְהִנֵּה אָמַר הַכָּתוּב בָּאָשָׁם "וְכִפֶּר", וְחָזַר וְאָמַר (ויקרא י"ד:י"ט) בַּחַטָּאת "וְכִפֶּר עַל הַמִּטַּהֵר מִטֻּמְאָתוֹ", וְאָמַר עוֹד בָּעוֹלָה וּבַמִּנְחָה (ויקרא י"ד:כ') "וְכִפֶּר עָלָיו הַכֹּהֵן וְטָהֵר", וְלֹא יָדַעְנוּ מַה עִנְיַן הַכַּפָּרוֹת הַלָּלוּ כֻּלָּן, אוּלַי הָאָשָׁם יְכַפֵּר עַל מַעֲלוֹ אֲשֶׁר מָעַל קֹדֶם נִגְעוֹ, וְהַחַטָּאת עַל חֶטְאוֹ אֲשֶׁר חָטָא בִּימֵי הַנֶּגַע, אוּלַי בְּצַעֲרוֹ נָתַן תִּפְלָה לֵאלֹהִים, וְזֶה טַעַם "מִטֻּמְאָתוֹ", וְהָעוֹלָה וְהַמִּנְחָה יִהְיוּ לוֹ כֹּפֶר נֶפֶשׁ שֶׁיִּזְכֶּה לִטָּהֵר וְלָשׁוּב אֶל אָהֳלוֹ, וּלְכָךְ אָמַר "וְכִפֶּר עָלָיו הַכֹּהֵן וְטָהֵר". וּבְת"כ (שם ג יג) "וְעָשָׂה הַכֹּהֵן אֶת הַחַטָּאת וְכִפֶּר", מַה תַּלְמוּד לוֹמַר, לְפִי שֶׁנֶּאֱמַר "וְהֶעֱלָה הַכֹּהֵן אֶת הָעֹלָה וְאֶת הַמִּנְחָה הַמִּזְבֵּחָה", יָכוֹל יְהוּ כֻּלָּן מְעַכְּבִים אוֹתוֹ, ת"ל "וְעָשָׂה הַכֹּהֵן אֶת הַחַטָּאת וְכִפֶּר", מְלַמֵּד שֶׁכַּפָּרָה תְּלוּיָה בַּחַטָּאת. וְיִתָּכֵן כִּי "וְכִפֶּר עָלָיו הַכֹּהֵן וְטָהֵר" רֶמֶז לְכָל הַנַּעֲשֶׂה בּוֹ, כִּי גַּם הַצִּפֳּרִים יָבוֹאוּ לְכַפָּרָה וּלְטַהֲרָה, כִּי כֵן אָמַר בְּנֶגַע הַבַּיִת (ויקרא י"ד:נ"ג) "וְכִפֶּר עַל הַבַּיִת וְטָהֵר":
@34 אָמַר הַכָּתוּב בְּנִגְעֵי הַבָּתִּים **וְנָתַתִּי נָגַע צָרַעַת** , לִרְמֹז כִּי יַד ה' תַּעֲשֶׂה זֹאת לֹא טֶבַע כְּלָל, כְּמוֹ שֶׁפֵּרַשְׁתִּי (רמב"ן על ויקרא י"ג:מ"ז). וְאָמַר "כִּי תָבוֹאוּ אֶל אֶרֶץ כְּנַעַן וְגוֹ' בְּבֵית אֶרֶץ אֲחֻזַּתְכֶם", כִּי עִם כָּל יִשְׂרָאֵל יְדַבֵּר. וְהָיָה רָאוּי אַחֲרֵי "וַיְדַבֵּר ה' אֶל מֹשֶׁה וְאֶל אַהֲרֹן" שֶׁיֹּאמַר "דַּבְּרוּ אֶל בְּנֵי יִשְׂרָאֵל", אֲבָל יְקַצֵּר הַכָּתוּב בַּמּוּבָן, אוֹ שֶׁיְּדַבֵּר עִמָּהֶם בִּמְקוֹם כָּל יִשְׂרָאֵל, וְיִרְמֹז כִּי אֵין הַכַּוָּנָה עַתָּה רַק לְלַמֵּד לָהֶם דִּינֵי הַצָּרַעַת כֻּלָּם וְשֶׁיְּלַמְּדוּ אוֹתָם לַכֹּהֲנִים, וְלֹא יַזְהִיר מֹשֶׁה עַתָּה אֶת כָּל יִשְׂרָאֵל רַק לְבָאֵי הָאָרֶץ יַזְהִיר (דברים כד ח) "הִשָּׁמֶר בְּנֶגַע הַצָּרַעַת לִשְׁמֹר מְאֹד" וְגוֹ', כִּי לָהֶם צִוָּה מִתְּחִלָּה הַמִּשְׁפָּטִים הָאֵלֶּה:
@43 **וְאִם יָשׁוּב הַנֶּגַע וּפָרַח בַּבַּיִת** הִנֵּה הַנֶּגַע הַזֶּה שֶׁבָּא בָּאֲבָנִים הָאֲחֵרוֹת וּבֶעָפָר הָאַחֵר אֵינֶנּוּ הַנֶּגַע הָרִאשׁוֹן, וְאֵינוֹ דּוֹמֶה לַפְּרִיחָה הָאֲמוּרָה בָּאָדָם וְלַפִּשְׂיוֹן, שֶׁהוּא שָׁב לִמְקוֹמוֹ הָרִאשׁוֹן בְּטִבְעוֹ, כִּי פְּעָמִים רַבִּים תִּסְתַּתֵּר הַלֵּחָה תַּחַת הָעוֹר וְתָשׁוּב אֶל פְּנִימִית הַגּוּף, וְאַחֲרֵי כֵן תָּשׁוּב וְתִמָּשֵׁךְ אֶל הָעוֹר וְאֶל חִיצוֹנָיו. אֲבָל הָעִנְיָן הוּא כַּאֲשֶׁר כָּתַבְתִּי בְּסֵדֶר אִשָּׁה כִּי תַזְרִיעַ (רמב"ן על ויקרא י"ג:מ"ז), שֶׁהוּא נֶגַע וּמַכַּת אֱלֹהִים שֶׁתִּהְיֶה רוּחַ ה' רָעָה בַּמָּקוֹם הַהוּא. וּבְתוֹרַת כֹּהֲנִים (פרשה ז א) אָמְרוּ, "וְאִם יָשׁוּב הַנֶּגַע וּפָרַח בַּבַּיִת", מָשָׁל חָזַר אִישׁ פְּלוֹנִי לִמְקוֹמוֹ. וְהַכַּוָּנָה לוֹמַר שֶׁאֵין "וּפָרַח" הָאָמוּר כָּאן פִּשְׂיוֹן, כְּמוֹ "וְאִם פָּרוֹחַ תִּפְרַח הַצָּרַעַת בָּעוֹר" (ויקרא י"ג:י"ב), אֶלָּא שֶׁהוּא צוֹמֵחַ בַּמָּקוֹם הַהוּא, כְּעִנְיַן "פָּרַח מַטֵּה אַהֲרֹן" (במדבר יז כג). וְהַמָּשָׁל שֶׁהִזְכִּירוּ לִרְמֹז הָעִנְיָן שֶׁאָמַרְנוּ, שֶׁאֵין זֶה נֶגַע נוֹלָד וּפוֹשֶׂה אֶלָּא צוֹמֵחַ וְחוֹזֵר וְצוֹמֵחַ, כְּאִישׁ שֶׁהָלַךְ לוֹ וְחָזַר לֵישֵׁב לִמְקוֹמוֹ הָרִאשׁוֹן בְּכִסֵּא אַחֵר אֲשֶׁר הוּכַן לוֹ שָׁם. וְטַעַם הַפְּרִיחָה כְּבָר פֵּרַשְׁתִּיהָ. וְכֵן צָרַעַת "פּוֹרַחַת הִיא" (ויקרא י"ג:נ"ז) בַּבְּגָדִים. וְלֹא אָמַר הַכָּתוּב "וְאִם יָשׁוּב הַנֶּגַע וּפָרַח בָּאֲבָנִים הָהֵם" אֶלָּא אֲפִלּוּ נוֹלַד בְּמָקוֹם אַחֵר מִן הַבַּיִת, וַאֲפִלּוּ מִמַּרְאֶה אַחֵר שֶׁאֵינוֹ כְּמַרְאֵה הַנֶּגַע הָרִאשׁוֹן, נָדוּן אוֹתוֹ כְּחוֹזֵר וּפוֹרֵחַ וְאֵינוֹ נִדּוֹן כְּנֶגַע הַנּוֹלָד מִתְּחִלָּה. וְזֶהוּ טַעַם "בַּבַּיִת", כִּי בְּכָל הַבַּיִת יִהְיֶה דִּינוֹ כֵן. וְהַטַּעַם כִּי הָרוּחַ הָרָעָה לֹא תָּסוּר מִן הַבַּיִת הַהוּא, אֲבָל תָּמִיד תִּהְיֶה בַּבַּיִת הַהוּא בְּאַחַת הַמְּקוֹמוֹת לְהַבְעִית אֶת בְּעָלָיו. וְכֵן אָמְרוּ בְּת"כ (פרשה ז א ג), אֵין לִי אֶלָּא מְקוֹמוֹ, מִנַּיִן לְרַבּוֹת אֶת כָּל הַבַּיִת, תַּלְמוּד לוֹמַר "בַּבַּיִת". אֵין לִי אֶלָּא בְּמַרְאָיו, שֶׁלֹּא בְּמַרְאָיו מִנַּיִן, ת"ל "וּפָרַח". וְעִנְיַן הַכְּתוּבִים הָאֵלֶּה כְּפִי הַמִּדְרָשׁ, וְאִם יָשׁוּב הַנֶּגַע בַּיּוֹם הַשְּׁבִיעִי וְחָזַר בַּבַּיִת אַחַר חִלֵּץ אֶת הָאֲבָנִים וְאַחֲרֵי הִקְצוֹת וְהִטֹּחַ, אוֹ בָּא הַכֹּהֵן בִּיאָה שֵׁנִית וְרָאָה וְהִנֵּה עַתָּה פָּשָׂה הַנֶּגַע בַּבַּיִת כַּמִּשְׁפָּט הָרִאשׁוֹן, צָרַעַת מַמְאֶרֶת הִיא, וְנָתַץ אֶת הַבַּיִת, לוֹמַר כִּי הַפּוֹשֶׂה בָּרִאשׁוֹן אוֹ הַפּוֹשֶׂה בַּשֵּׁנִי מִשְׁפָּט אֶחָד לָהֶם. וְלֹא הֻצְרַךְ לוֹמַר "וּבָא הַכֹּהֵן וְרָאָה וְהִנֵּה פָּשָׂה הַנֶּגַע בַּבָּיִת וְצִוָּה וְחִלְּצוּ אֶת הָאֲבָנִים" וְכָל הַפָּרָשָׁה, כִּי הַכָּתוּב נִמְשָׁךְ לְמַעְלָה, לֵאמֹר אִם יָשׁוּב הַנֶּגַע אַחַר חִלֵּץ הָאֲבָנִים בָּרִאשׁוֹן אוֹ בַּשֵּׁנִי כַּאֲשֶׁר בָּא הַכֹּהֵן וְרָאָה הַפִּשְׂיוֹן - צָרַעַת מַמְאֶרֶת הִיא. וְאָמַר עוֹד (ויקרא י"ד:מ"ח) "וְאִם בֹּא יָבֹא הַכֹּהֵן" בַּבִּיאָה הַשֵּׁנִית הַנִּזְכֶּרֶת, "וְרָאָה וְהִנֵּה לֹא פָשָׂה הַנֶּגַע בַּבַּיִת אַחֲרֵי הִטֹּחַ אֶת הַבָּיִת", וְטִהַר הַכֹּהֵן אֶת הַבַּיִת כַּאֲשֶׁר נִרְפָּא הַנֶּגַע מִמֶּנּוּ, כְּלוֹמַר שֶׁלֹּא חָזַר בּוֹ. וְנִלְמַד עַתָּה שֶׁהָעוֹמֵד בְּעֵינָיו בָּרִאשׁוֹן וּבַשֵּׁנִי - חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ, וְאִם חָזַר - נוֹתֵץ. וְזֶה תִּקּוּן הַמִּקְרָאוֹת כְּמִדְרָשָׁם, שֶׁאִי אֶפְשָׁר לְחָתְכָם בְּסַכִּין לְהַקְדִּים וּלְאַחֵר בְּדָבָר שֶׁאֵינוֹ כְּלָל בְּמַשְׁמָעָם. וְיִתָּכֵן עוֹד שֶׁנֹּאמַר בְּתִקּוּן הָעִנְיָן הַזֶּה, כִּי "פָּשָׂה" בַּמָּקוֹם הַזֶּה כְּטַעַם "פָּרַח", וּשְׁנֵיהֶם עִנְיַן צְמִיחָה, כִּי כְּשֶׁיֵּשׁ שָׁם נֶגַע יֹאמַר פָּשָׂה בְּגִדּוּלוֹ וְהִתְפַּשְּׁטוֹ, וּכְשֶׁאֵין שָׁם נֶגַע יֹאמַר פָּשָׂה בִּצְמִיחָתוֹ וְשׁוּבוּ, כִּי הַכֹּל עִנְיַן גִּדּוּל. וְכֵן אוּנְקְלוֹס פָּתַר בְּכֻלָּן "אוֹסֵיף", וּלְשׁוֹן תּוֹסֶפֶת יֵאָמֵר בְּדָבָר הַגָּדֵל וְנוֹסָף עַל הָאַחֵר, כְּגוֹן "וְנוֹסַף גַּם הוּא עַל שֹׂנְאֵינוּ" (שמות א י), "וְנוֹסְפָה נַחֲלָתָן" (במדבר לו ד), וְיֵאָמֵר בְּדָבָר הַחוֹזֵר, כְּגוֹן "יוֹסִיף ה' שֵׁנִית יָדוֹ" (ישעיהו יא יא), "וַיִּתְנַבְּאוּ וְלֹא יָסָפוּ" (במדבר יא כה), לֹא חָזְרוּ עוֹד לְהִנָּבֵא. וְהִנֵּה עִנְיָנוֹ שֶׁחָזַר הַנֶּגַע. וְהִנֵּה אַחַר חִלֵּץ הָאֲבָנִים כְּשֶׁיַּזְכִּיר הַכָּתוּב פִּשְׂיוֹן יִהְיֶה עִנְיָנוֹ כְּטַעַם צְמִיחָה, כַּאֲשֶׁר הִזְכַּרְתִּי בְּמִלַּת פְּרִיחָה, וְאִם כֵּן יֹאמַר הַכָּתוּב, וְאִם יָשׁוּב הַנֶּגַע וְצָמַח בַּבַּיִת אַחַר חִלֵּץ הָאֲבָנִים, וּבָא הַכֹּהֵן וְרָאָה וְהִנֵּה צָמַח הַנֶּגַע בַּבַּיִת, וְנָתַץ אוֹתוֹ, כִּי כָּל נֶגַע הַחוֹזֵר טָמֵא מֻחְלָט. וְאִם בֹּא יָבֹא הַכֹּהֵן וְרָאָה שֶׁלֹּא צָמַח הַנֶּגַע כְּלָל בַּבַּיִת אַחֲרֵי הִטֹּחַ - יְטַהֲרֶנּוּ, כִּי נִרְפָּא בַּחֲלִיצָה וְטִיחָה. וְהִנֵּה נִתְפָּרֵשׁ כָּאן דִּין הַבַּיִת בְּפוֹשֶׂה בָּרִאשׁוֹן שֶׁחוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ, וְאִם חָזַר טָמֵא וְאִם לֹא חָזַר טָהוֹר. אֲבָל הָעוֹמֵד בְּעֵינָיו בָּרִאשׁוֹן וּפוֹשֶׂה בַּשֵּׁנִי, לֹא נִתְפָּרֵשׁ בַּתּוֹרָה דִּינוֹ, אֲבָל נָדוּן בּוֹ גְּזֵרָה שָׁוָה, זוֹ הִיא בִּיאָה זוֹ הִיא שִׁיבָה (תורת כהנים ז ז), לוֹמַר שֶׁדִּין הַבִּיאָה שֶׁהִיא אֲמוּרָה בְּסוֹף שָׁבוּעַ שֵׁנִי כְּדִין הַשִּׁיבָה שֶׁהִיא אֲמוּרָה בְּסוֹף שָׁבוּעַ רִאשׁוֹן, שֶׁבִּשְׁתֵּיהֶן אִם פָּשָׂה בּוֹ חוֹלֵץ וְקוֹצֶה וְטָח וְנוֹתֵן לוֹ שָׁבוּעַ. וְכֵן הָעוֹמֵד בְּעֵינָיו בָּרִאשׁוֹן וּבַשֵּׁנִי וּפוֹשֶׂה בַּשְּׁלִישִׁי לֹא הֻזְכַּר בַּתּוֹרָה, אֲבָל נִלְמַד (בתורת כהנים שם ה-י) מִגְּזֵרָה שָׁוָה אַחֶרֶת, שֶׁאָמַר (ויקרא י"ד:מ"ח) "וְאִם בֹּא יָבֹא הַכֹּהֵן", שֶׁנָּדוּן בִּיאָה שְׁלִישִׁית כְּבִיאָה שְׁנִיָּה. וְהִנֵּה הַכְּתוּבִים כְּמַשְׁמָעָם, וְהַמִּדְרָשׁוֹת לָמְדוּ אוֹתָן מִגְּזֵרָה שָׁוָה לְמֹשֶׁה בְּסִינַי. וּמַה שֶׁאָמְרוּ בְּת"כ (פרשה ז ז), בַּמֶּה הַכָּתוּב מְדַבֵּר וכו', סֶמֶךְ מִדִּבְרֵיהֶם, שֶׁיִּרְצוּ לְהַזְכִּיר בַּכָּתוּב הָעִנְיָן הַמְקֻבָּל לָהֶם בִּגְזֵרָה שָׁוָה. וְכֵן מַה שֶׁאָמְרוּ שָׁם (בתורת כהנים פרשה ז ו), אִם סוֹפֵנוּ לְרַבּוֹת אֶת הַחוֹזֵר אע"פ שֶׁאֵינוֹ פוֹשֶׂה, מַה ת"ל "וּבָא הַכֹּהֵן וְרָאָה וְהִנֵּה פָּשָׂה", הַנַּח לוֹ. לוֹמַר, שֶׁנַּנִּיחַ הַכָּתוּב כְּמַשְׁמָעוּתוֹ וְנֵלֵךְ אַחַר הַמִּדְרָשׁ, לֹא שֶׁנַּעֲקֹר הַכָּתוּב מִמְּקוֹמוֹ וְנִקְבָּעֶנּוּ בְּמָקוֹם אַחֵר. זֶהוּ הַנִּרְאֶה אֵלַי בְּעִנְיַן הַפָּרָשָׁה הַזֹּאת כְּדֵי שֶׁיְּהוּ דִּבְרֵי חֲכָמִים קַיָּמִים, וְהוּא דָּבָר נָאֶה וּמִתְקַבֵּל:
@53 **וְכִפֶּר עַל הַבַּיִת וְטָהֵר** הִנֵּה הַכַּפָּרָה הַזֹּאת בַּצִּפּוֹר הַמִּשְׁתַּלַּחַת, שֶׁתִּשָּׂא הַצִּפּוֹר אֶת כָּל עֲוֹנֹתָיו אֶל מִחוּץ לָעִיר אֶל פְּנֵי הַשָּׂדֶה, כְּעִנְיַן הַכַּפָּרָה בְּשָׂעִיר הַמִּשְׁתַּלֵּחַ. וּבַעֲבוּר שֶׁאֵין עֹנֶשׁ הַנֶּגַע הַנִּרְאֶה בְּבֵיתוֹ שֶׁל אָדָם כְּעֹנֶשׁ הַנֶּגַע שֶׁבְּגוּפוֹ, לֹא הִצְרִיכוֹ הַכָּתוּב לְאָשָׁם וְחַטָּאת, כִּי דַּי לוֹ בַּכַּפָּרָה הָרִאשׁוֹנָה שֶׁיָּבִיא הַמְּצֹרָע לְטָהֳרָתוֹ, שֶׁהֵם הַצִּפֳּרִים וְעֵץ הָאֶרֶז וְהָאֵזוֹב:
@54 **זֹאת הַתּוֹרָה לְכָל נֶגַע הַצָּרַעַת** הוּא צָרַעַת הַשְּׁחִין וְהַמִּכְוָה, וְהִזְכִּירָם בְּכָאן תְּחִלָּה מִפְּנֵי תְּדִירוּתָן, וְאַחֲרֵי כֵן הִזְכִּיר הַנֶּתֶק שֶׁהוּא גַּם כֵּן מָצוּי, וְאַחֲרֵי כֵן הִזְכִּיר צָרַעַת הַבֶּגֶד וְהַבַּיִת, וְאַחֲרֵי כֵן אָמַר "וְלַשְׂאֵת וְלַסַּפַּחַת וְלַבֶּהָרֶת", הֵם הַנְּגָעִים הָרִאשׁוֹנִים שֶׁפָּתַח בָּהֶם (ויקרא י"ג:ב') "אָדָם כִּי יִהְיֶה בְעוֹר בְּשָׂרוֹ" וְגוֹ'. וּבְכָל מָקוֹם יְאַחֵר הַבַּהֶרֶת בַּעֲבוּר שֶׁהִיא הָעַזָּה וְהַקָּשָׁה שֶׁבְּכֻלָּן:
@68 **וְיָדָיו לֹא שָׁטַף בַּמָּיִם** יִקְרָא הַכָּתוּב הַטְּבִילָה - שְׁטִיפָה בַּמַּיִם, שֶׁאָמַר בְּכָאן "וְכָל כְּלִי עֵץ יִשָּׁטֵף בַּמָּיִם", וְכֵן יִקְרָאֶנָּה בִּבְגָדִים כִּבּוּס, "וְכֻבַּס שֵׁנִית וְטָהֵר" (ויקרא י"ג:נ"ח). וְהַטַּעַם בַּעֲבוּר כִּי הַטְּבִילָה צְרִיכָה שֶׁלֹּא יִהְיֶה בָּהּ דָּבָר חוֹצֵץ אֶלָּא יִשְׁטֹף כָּל גּוּפוֹ בְּמַיִם, כִּלְשׁוֹן "וּמֹרַק וְשֻׁטַּף בַּמָּיִם" (ויקרא ו':כ"א), וְכֵן "נַחַל שׁוֹטֵף" (ירמיהו מז ב). וְעִנְיַן הַכָּתוּב, בַּעֲבוּר כִּי הַנְּגִיעָה בַּיָּדַיִם אָמַר כִּי אֲשֶׁר יִגַּע בּוֹ הַזָּב בְּיָדָיו וַעֲדַיִן לֹא שָׁטַף אוֹתָם בִּשְׁטִיפַת כָּל גּוּפוֹ בַּמַּיִם - יִהְיֶה טָמֵא, כְּאִלּוּ אָמַר, וְכֹל אֲשֶׁר יִגַּע בּוֹ הַזָּב בְּיָדָיו וַעֲדַיִן לֹא רָחַץ בַּמַּיִם בְּיוֹם טָהֳרָתוֹ - יְכַבֵּס בְּגָדָיו. וְהֻצְרַךְ לוֹמַר לְשׁוֹן שְׁטִיפָה לְלַמֵּד עַל הָרְחִיצָה שֶׁיַּזְכִּיר (ויקרא ט"ו:י"ג) "וְרָחַץ בְּשָׂרוֹ בְּמַיִם חַיִּים", שֶׁתִּהְיֶה בִּשְׁטִיפָה וְשִׁפְשׁוּף לְהָסִיר הַחֲצִיצָה כְּמוֹ שֶׁפֵּרַשְׁתִּי. וְאֵינֶנּוּ נָכוֹן שֶׁיֹּאמַר כִּי אֲשֶׁר יִגַּע בּוֹ הַזָּב אַחֲרֵי שֶׁיִּשְׁטֹף יָדָיו בַּמַּיִם לֹא יִטְמָא, שֶׁכְּבָר אָמַר כִּי כָל הַנֹּגֵעַ בִּבְשַׂר הַזָּב בְּאֵי זֶה מָקוֹם שֶׁיִּהְיֶה מִמֶּנּוּ יִטְמָא, וְכֵן בְּמִשְׁכָּבוֹ וּמֶרְכָּבוֹ וּבַכְּלִי אֲשֶׁר יֵשֵׁב עָלָיו, עַד אֲשֶׁר יִטְהַר מִזּוֹבוֹ וְרָחַץ בְּשָׂרוֹ בְּמַיִם חַיִּים וְטָהֵר. אֲבָל הַכָּתוּב יִרְמֹז לְטָהֳרָתוֹ בִּטְבִילָה גְּמוּרָה כְּמוֹ שֶׁפֵּרַשְׁתִּי. וְרַבּוֹתֵינוּ אָמְרוּ (תורת כהנים זבים פרק ד ה), שֶׁהוֹצִיא הַכָּתוּב טְבִילַת גּוּפוֹ שֶׁל זָב בִּלְשׁוֹן שְׁטִיפַת יָדַיִם לְלַמֶּדְךָ שֶׁאֵין בֵּית הַסְּתָרִים טָעוּן בִּיאַת מַיִם אֶלָּא אֵבָר הַגָּלוּי, כְּמוֹ הַיָּדַיִם. וְטַעַם טֻמְאַת הַזּוֹב בָּאִישׁ, מִפְּנֵי הֱיוֹתוֹ חֹלִי כָּבֵד מִן הֶחֳלָיִים הַנִּדְבָּקִים, וְצָרִיךְ קָרְבָּן לָתֵת הוֹדָאָה לַשֵּׁם שֶׁרִפֵּא אוֹתוֹ וְטִהֲרוֹ, וְצָרִיךְ חַטָּאת לְכַפֵּר עַל חֶטְאוֹ שֶׁלֹּא יִגְרֹם לוֹ עוֹד חֹלִי. וְטַעַם טֻמְאַת שִׁכְבַת זֶרַע (ויקרא ט"ו:ט"ז-י"ח), אע"פ שֶׁהוּא בְּטֶבַע הַתּוֹלָדָה, כְּטַעַם טֻמְאַת הַמֵּת, כִּי הַמָּקוֹר מָשְׁחָת, וְהַשּׁוֹכֵב לֹא יוֹדֵעַ אִם יִשָּׁחֵת זַרְעוֹ אוֹ יִהְיֶה מִמֶּנּוּ וָלָד נוֹצָר. וּבְזָכְרִי טֻמְאַת הַמֵּת בְּעֶזְרַת הַמֵּמִית וְהַמְּחַיֶּה יִתְבָּאֵר לְךָ הַקֶּרִי. וְעוֹד אַזְכִּיר בַּנִּדָּה (רמב"ן על ויקרא י"ח:י"ט) עִקָּרִים, הֵקֵל הַכָּתוּב בְּזוֹב הָאִשָּׁה בְּעֵת נִדָּתָהּ וְלֹא חִיֵּב בָּהּ קָרְבָּן, בַּעֲבוּר שֶׁהוּא בְּטִבְעָהּ וְלֹא נִתְרַפֵּאת מֵחֹלִי, וְטִמֵּא אֹתָהּ שִׁבְעַת יָמִים בֵּין שֶׁתִּרְאֶה יוֹם אֶחָד אוֹ כָּל הַשִּׁבְעָה, כִּי הַנָּשִׁים בְּטִבְעָן לֹא תִּהְיֶה בָּהֶן יוֹתֵר מִשִּׁבְעָה זוּלָתִי בִּהְיוֹת בָּהֶן שֶׁפַע יָתֵר בְּחֹלִי, אֲבָל כִּי יָזוּב זוֹב דָּמָהּ יָמִים רַבִּים בְּלֹא עֶת הַיָּדוּעַ לָהּ, אוֹ שֶׁתּוֹסִיף עַל הָעֵת וְיָזוּב זוֹב דָּמָהּ יָמִים רַבִּים אַחֲרֵי הַשִּׁבְעָה הָהֵם, הִנֵּה הוּא חֹלִי כְּזוֹב הָאִישׁ, וְהִצְרִיךְ אוֹתָהּ קָרְבָּן בְּהִתְרַפּאוֹתָהּ כְּדִין הַזָּב. וְלֹא הִזְכִּיר הַכָּתוּב טְבִילָה בָּאִשָּׁה כִּי הִזְכִּיר זוֹב הָאִישׁ וְטֻמְאָתוֹ וְאָמַר בַּסּוֹף (ויקרא ט"ו:י"ג) "וְרָחַץ בְּשָׂרוֹ בְּמַיִם חַיִּים וְטָהֵר", וְחָזַר וְאָמַר בָּאִשָּׁה (ויקרא ט"ו:י"ט) "וְאִשָּׁה כִּי תִהְיֶה זָבָה" כָּאִישׁ הַזָּב, דָּם יִהְיֶה הַזּוֹב שֶׁלָּהּ, לֹא לֹבֶן כָּאִישׁ, וְהִזְכִּיר הַטֻּמְאָה בְּנִדָּה וּבְזָבָה, וְאַחֲרֵי כֵן הִזְכִּיר בְּזָבָה (ויקרא ט"ו:כ"ח) "וְאִם טָהֲרָה מִזּוֹבָהּ" כַּאֲשֶׁר יִטְהַר הַזָּב מִזּוֹבוֹ, "וְסָפְרָה לָּהּ שִׁבְעַת יָמִים" כַּאֲשֶׁר יִסְפֹּר הַזָּב, "וְאַחַר תִּטְהָר", כְּטַהֲרַת הַזָּב. וְעַל דֶּרֶךְ הַפְּשָׁט שֶׁתִּהְיֶה צְרִיכָה רְחִיצָה בְּמַיִם חַיִּים כַּזָּב. אֲבָל רַבּוֹתֵינוּ הֵקֵלּוּ בְּטָהֳרַת הַזָּבָה שֶׁתִּטְהַר כְּדֶרֶךְ שְׁאָר הַנִּטְהָרִים מִטֻּמְאָתָם בְּמֵי מִקְוֶה (תוספתא מגילה פ"א הי"א). וְהַטַּעַם לָהֶם מִפְּנֵי שֶׁלֹּא הָיָה צָרִיךְ לְהַזְכִּיר כְּלָל "וְאַחַר תִּטְהָר", שֶׁבִּכְלַל הָאִישׁ הִיא, שֶׁלֹּא בָּא הַכָּתוּב אֶלָּא לְהַזְכִּיר הַחִלּוּק שֶׁבֵּין הַזָּכָר לַנְּקֵבָה, שֶׁיִּהְיֶה זֹבָהּ בְּדָם, וּלְחַלֵּק בֵּין עֵת נִדָּתָהּ וּבֵין בְּלֹא עִתָּהּ, וּלְפִיכָךְ סָבְרוּ שֶׁבָּא הַכָּתוּב לְרַבּוֹת לָהּ טַהֲרָה, לוֹמַר "וְאַחַר תִּטְהָר" כַּנִּטְהָרִים בַּתּוֹרָה, גַּם בְּלֹא מַיִם חַיִּים:
